{"command":"cd /workspace/src && cat > buffer.c <<'EOF'
#include "duc.h"

struct buffer *buffer_new(const void *data, size_t len)
{
	struct buffer *b = calloc(1, sizeof *b);
	if(data) {
		b->data = malloc(len ? len : 1);
		memcpy(b->data, data, len);
		b->len = len;
		b->alloc = len;
	} else {
		b->alloc = 1024;
		b->data = malloc(b->alloc);
	}
	return b;
}

void buffer_free(struct buffer *b)
{
	if(!b) return;
	free(b->data);
	free(b);
}

void buffer_put(struct buffer *b, const void *data, size_t len)
{
	if(b->len + len > b->alloc) {
		while(b->len + len > b->alloc) b->alloc = b->alloc * 2 + 16;
		b->data = realloc(b->data, b->alloc);
	}
	memcpy(b->data + b->len, data, len);
	b->len += len;
}

/* sqlite4 style variable length integer */
void buffer_put_varint(struct buffer *b, uint64_t v)
{
	uint8_t buf[9];
	int n = 0;
	if(v <= 240) {
		buf[0] = v; n = 1;
	} else if(v <= 2287) {
		buf[0] = (v - 240) / 256 + 241;
		buf[1] = (v - 240) % 256;
		n = 2;
	} else if(v <= 67823) {
		buf[0] = 249;
		buf[1] = (v - 2288) / 256;
		buf[2] = (v - 2288) % 256;
		n = 3;
	} else {
		int bytes;
		if(v <= 0xffffffULL) bytes = 3;
		else if(v <= 0xffffffffULL) bytes = 4;
		else if(v <= 0xffffffffffULL) bytes = 5;
		else if(v <= 0xffffffffffffULL) bytes = 6;
		else if(v <= 0xffffffffffffffULL) bytes = 7;
		else bytes = 8;
		buf[0] = 247 + bytes;
		for(int i=0; i<bytes; i++) {
			buf[1+i] = (v >> (8 * (bytes - 1 - i))) & 0xff;
		}
		n = bytes + 1;
	}
	buffer_put(b, buf, n);
}

void buffer_put_string(struct buffer *b, const char *s)
{
	size_t l = strlen(s);
	buffer_put_varint(b, l);
	buffer_put(b, s, l);
}

int buffer_get_varint(struct buffer *b, uint64_t *v)
{
	if(b->ptr >= b->len) return -1;
	uint8_t *p = b->data + b->ptr;
	size_t avail = b->len - b->ptr;
	uint8_t a0 = p[0];
	if(a0 <= 240) {
		*v = a0; b->ptr += 1; return 0;
	}
	if(a0 <= 248) {
		if(avail < 2) return -1;
		*v = 240 + 256 * (uint64_t)(a0 - 241) + p[1];
		b->ptr += 2; return 0;
	}
	if(a0 == 249) {
		if(avail < 3) return -1;
		*v = 2288 + 256 * (uint64_t)p[1] + p[2];
		b->ptr += 3; return 0;
	}
	int bytes = a0 - 247;
	if(avail < (size_t)bytes + 1) return -1;
	uint64_t r = 0;
	for(int i=0; i<bytes; i++) r = (r << 8) | p[1+i];
	*v = r;
	b->ptr += bytes + 1;
	return 0;
}

int buffer_get_string(struct buffer *b, char **s)
{
	uint64_t l;
	if(buffer_get_varint(b, &l) != 0) return -1;
	if(b->ptr + l > b->len) return -1;
	char *r = malloc(l + 1);
	memcpy(r, b->data + b->ptr, l);
	r[l] = 0;
	b->ptr += l;
	*s = r;
	return 0;
}
EOF
echo ok"}

