struct db {
	sqlite3 *s;
	int write;
};

struct db *db_open(const char *path, int write, duc_errno *err)
{
	struct db *db = calloc(1, sizeof *db);
	int mode = write ? (SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE) : SQLITE_OPEN_READONLY;
	int r = sqlite3_open_v2(path, &db->s, mode, NULL);
	if(r != SQLITE_OK) {
		*err = E_DB_NOT_FOUND;
		if(db->s) sqlite3_close(db->s);
		free(db);
		return NULL;
	}
	r = sqlite3_exec(db->s, "create table if not exists blobs(key unique primary key, value)", 0, 0, 0);
	if(r != SQLITE_OK && r != SQLITE_READONLY) {
		if(r == SQLITE_CANTOPEN) *err = E_DB_NOT_FOUND;
		else *err = E_DB_CORRUPT;
		sqlite3_close(db->s);
		free(db);
		return NULL;
	}
	sqlite3_exec(db->s, "create index if not exists keys on blobs(key)", 0, 0, 0);
	db->write = write;
	if(write) sqlite3_exec(db->s, "begin", 0, 0, 0);
	return db;
}

void db_close(struct db *db)
{
	if(!db) return;
	if(db->write) sqlite3_exec(db->s, "commit", 0, 0, 0);
	sqlite3_close(db->s);
	free(db);
}

int db_put(struct db *db, const void *key, size_t klen, const void *val, size_t vlen)
{
	sqlite3_stmt *st;
	int r = sqlite3_prepare_v2(db->s, "insert or replace into blobs(key, value) values(?, ?)", -1, &st, 0);
	if(r != SQLITE_OK) return -1;
	sqlite3_bind_text(st, 1, key, klen, SQLITE_STATIC);
	sqlite3_bind_blob(st, 2, val, vlen, SQLITE_STATIC);
	r = sqlite3_step(st);
	sqlite3_finalize(st);
	return (r == SQLITE_DONE) ? 0 : -1;
}

void *db_get(struct db *db, const void *key, size_t klen, size_t *vlen)
{
	sqlite3_stmt *st;
	void *res = NULL;
	int r = sqlite3_prepare_v2(db->s, "select value from blobs where key = ?", -1, &st, 0);
