#include "duc.h"
#include <stdarg.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

int g_loglevel = LOG_WRN;
const char *g_argv0 = "duc";

void duc_log(int level, const char *fmt, ...)
{
	if(level > g_loglevel) return;
	va_list va;
	va_start(va, fmt);
	vfprintf(stderr, fmt, va);
	va_end(va);
	fputc('\n', stderr);
}

char *duc_default_db_path(void)
{
	char *p = getenv("DUC_DATABASE");
	if(p) return strdup(p);
	char *home = getenv("HOME");
	if(home) {
		char old[8192];
		snprintf(old, sizeof old, "%s/.duc.db", home);
		struct stat st;
		if(stat(old, &st) == 0) {
			duc_log(LOG_WRN, "Using old database at \"%s\", please move this to \"$XDG_CACHE_HOME/duc/duc.db\"", old);
			return strdup(old);
		}
	}
	char *xdg = getenv("XDG_CACHE_HOME");
	char buf[8192];
	if(xdg) {
		snprintf(buf, sizeof buf, "%s/duc/duc.db", xdg);
		return strdup(buf);
	}
	if(home) {
		snprintf(buf, sizeof buf, "%s/.cache/duc/duc.db", home);
		return strdup(buf);
	}
	return NULL;
}

static int type_check_ok(const char *path)
{
	FILE *f = fopen(path, "r");
	if(!f) return 0;
	char buf[16];
	memset(buf, 0, sizeof buf);
	size_t n = fread(buf, 1, sizeof buf, f);
	fclose(f);
	if(n < 15) return 0;
	if(memcmp(buf, "SQLite format 3", 15) == 0) return 1;
	return 0;
}

int duc_open(struct duc *duc, const char *path, int write)
{
	if(path == NULL) {
		duc->err = E_DB_NOT_FOUND;
		return -1;
	}
	duc->db_path = strdup(path);
	duc->db = db_open(path, write, &duc->err);
	if(duc->db == NULL) {
		duc_log(LOG_FTL, "Error opening: %s - %s", path, duc_strerror(duc->err));
		return -1;
	}
	if(!type_check_ok(path)) {
		duc_log(LOG_FTL, "Error opening: %s - unsupported DB type _unknown_, duc compiled for sqlite3", path);
		db_close(duc->db);
		duc->db = NULL;
		duc->err = E_DB_TYPE_MISMATCH;
		return -1;
	}
	return 0;
}

void duc_close(struct duc *duc)
{
	if(duc->db) db_close(duc->db);
	duc->db = NULL;
}

/* Path normalization: make absolute and remove ., .. and duplicate slashes */
char *path_normalize(const char *path)
{
	char *full;
	if(path[0] == '/') {
		full = strdup(path);
	} else {
		char cwd[16384];
		if(getcwd(cwd, sizeof cwd) == NULL) cwd[0] = 0;
		full = malloc(strlen(cwd) + strlen(path) + 2);
		sprintf(full, "%s/%s", cwd, path);
	}
	size_t n = strlen(full);
	char **comp = malloc(sizeof(char *) * (n + 1));
	int nc = 0;
	char *save = NULL;
	for(char *t = strtok_r(full, "/", &save); t; t = strtok_r(NULL, "/", &save)) {
		if(strcmp(t, ".") == 0) continue;
		if(strcmp(t, "..") == 0) {
			if(nc > 0) nc--;
			continue;
		}
		comp[nc++] = t;
	}
	char *out = malloc(n + 2);
	out[0] = 0;
	size_t ol = 0;
	for(int i=0; i<nc; i++) {
		out[ol++] = '/';
		size_t l = strlen(comp[i]);
		memcpy(out + ol, comp[i], l);
		ol += l;
	}
	if(ol == 0) out[ol++] = '/';
	out[ol] = 0;
	free(comp);
	free(full);
	return out;
}

int64_t size_get(const struct size3 *s, int st)
{
	if(st == ST_APPARENT) return s->apparent;
	if(st == ST_COUNT) return s->count;
	return s->actual;
}

/* dir records */

static struct ddir *ddir_parse(const void *data, size_t len)
{
	struct ddir *d = calloc(1, sizeof *d);
	struct buffer *b = buffer_new(data, len);
	uint64_t v;
	buffer_get_varint(b, &v); d->parent.dev = v;
	buffer_get_varint(b, &v); d->parent.ino = v;
	buffer_get_varint(b, &v); d->mtime = v;
	while(b->ptr < b->len) {
		struct dirent_d e;
		memset(&e, 0, sizeof e);
		if(buffer_get_string(b, &e.name) != 0) break;
		buffer_get_varint(b, &v); e.size.apparent = v;
		buffer_get_varint(b, &v); e.size.actual = v;
		buffer_get_varint(b, &v); e.size.count = v;
		buffer_get_varint(b, &v); e.type = v;
		if(e.type == FT_DIR) {
			buffer_get_varint(b, &v); e.devino.dev = v;
			buffer_get_varint(b, &v); e.devino.ino = v;
		}
		if(d->ent_count >= d->ent_alloc) {
			d->ent_alloc = d->ent_alloc * 2 + 16;
			d->ent = realloc(d->ent, d->ent_alloc * sizeof *d->ent);
		}
		d->ent[d->ent_count++] = e;
		d->size.apparent += e.size.apparent;
		d->size.actual += e.size.actual;
		d->size.count += e.size.count;
	}
	buffer_free(b);
	return d;
}

struct ddir *ddir_load(struct duc *duc, struct devino *di)
{
	char key[64];
	snprintf(key, sizeof key, "%jx/%jx", (uintmax_t)di->dev, (uintmax_t)di->ino);
	size_t vlen;
	void *v = db_get(duc->db, key, strlen(key), &vlen);
	if(!v) return NULL;
	struct ddir *d = ddir_parse(v, vlen);
	free(v);
	d->devino = *di;
	return d;
}

void ddir_free(struct ddir *d)
{
	if(!d) return;
	for(size_t i=0; i<d->ent_count; i++) free(d->ent[i].name);
	free(d->ent);
	free(d->path);
	free(d);
}

struct ddir *ddir_open(struct duc *duc, const char *path_in)
{
	char *path = path_normalize(path_in);
	/* find the longest report path which is a prefix */
	char *tmp = strdup(path);
	struct report *r = NULL;
	size_t plen = strlen(path);
	size_t cut = plen;
	for(;;) {
		tmp[cut] = 0;
		const char *k = cut == 0 ? "/" : tmp;
		r = report_load(duc, k);
		if(r) break;
		if(cut == 0) break;
		while(cut > 0 && tmp[cut-1] != '/') cut--;
		if(cut > 0) cut--; /* remove the slash */
		if(cut == 0 && strcmp(k, "/") == 0) break;
	}
	if(!r) {
		duc_log(LOG_FTL, "Path %s not found in database", path);
		duc->err = E_PATH_NOT_FOUND;
		free(tmp); free(path);
		return NULL;
	}
	struct ddir *d = ddir_load(duc, &r->devino);
	report_free(r);
	if(!d) {
		duc->err = E_PATH_NOT_FOUND;
		free(tmp); free(path);
		return NULL;
	}
	/* descend remaining components */
	char *rest = strdup(path + cut);
	char *save = NULL;
	for(char *t = strtok_r(rest, "/", &save); t; t = strtok_r(NULL, "/", &save)) {
		struct dirent_d *found = NULL;
		for(size_t i=0; i<d->ent_count; i++) {
			if(strcmp(d->ent[i].name, t) == 0 && d->ent[i].type == FT_DIR) {
				found = &d->ent[i];
				break;
			}
		}
		if(!found) {
			ddir_free(d);
			d = NULL;
			break;
		}
		struct devino di = found->devino;
		ddir_free(d);
		d = ddir_load(duc, &di);
		if(!d) break;
	}
	free(rest);
	free(tmp);
	if(!d) {
		duc->err = E_PATH_NOT_FOUND;
		free(path);
		return NULL;
	}
	d->path = path;
	return d;
}

struct ddir *ddir_openent(struct duc *duc, struct ddir *dir, struct dirent_d *e)
{
	if(e->type != FT_DIR) return NULL;
	struct ddir *d = ddir_load(duc, &e->devino);
	if(!d) return NULL;
	size_t l = strlen(dir->path) + strlen(e->name) + 2;
	d->path = malloc(l);
	if(strcmp(dir->path, "/") == 0) snprintf(d->path, l, "/%s", e->name);
	else snprintf(d->path, l, "%s/%s", dir->path, e->name);
	return d;
}

static int g_sort_st;

static int cmp_name(const void *a, const void *b)
{
	const struct dirent_d *ea = a, *eb = b;
	return strcmp(ea->name, eb->name);
}

static int cmp_size(const void *a, const void *b)
{
	const struct dirent_d *ea = a, *eb = b;
	int64_t sa, sb;
	if(g_sort_st == ST_COUNT) {
		sa = ea->size.count; sb = eb->size.count;
		if(sa < sb) return 1;
		if(sa > sb) return -1;
		return strcmp(ea->name, eb->name);
	}
	if(g_sort_st == ST_APPARENT) {
		sa = ea->size.apparent; sb = eb->size.apparent;
		if(sa < sb) return 1;
		if(sa > sb) return -1;
		sa = ea->size.actual; sb = eb->size.actual;
		if(sa < sb) return 1;
		if(sa > sb) return -1;
		return strcmp(ea->name, eb->name);
	}
	sa = ea->size.actual; sb = eb->size.actual;
	if(sa < sb) return 1;
	if(sa > sb) return -1;
	sa = ea->size.apparent; sb = eb->size.apparent;
	if(sa < sb) return 1;
	if(sa > sb) return -1;
	return strcmp(ea->name, eb->name);
}

void ddir_sort(struct ddir *d, int st, int sort)
{
	g_sort_st = st;
	if(d->ent_count == 0) return;
	qsort(d->ent, d->ent_count, sizeof *d->ent, sort == SORT_NAME ? cmp_name : cmp_size);
}

/* reports */

int report_get_list(struct duc *duc, char ***list, size_t *count)
{
	size_t vlen = 0;
	char *v = db_get(duc->db, "duc_index_reports", strlen("duc_index_reports"), &vlen);
	*list = NULL;
	*count = 0;
	if(!v) return 0;
	size_t n = vlen / DUC_PATH_SLOT;
	char **l = calloc(n + 1, sizeof(char *));
	size_t c = 0;
	for(size_t i=0; i<n; i++) {
		char *p = v + i * DUC_PATH_SLOT;
		size_t len = strnlen(p, DUC_PATH_SLOT);
		l[c] = malloc(len + 1);
		memcpy(l[c], p, len);
		l[c][len] = 0;
		c++;
	}
	free(v);
	*list = l;
	*count = c;
	return 0;
}

struct report *report_parse(const void *data, size_t len)
{
	struct report *r = calloc(1, sizeof *r);
	struct buffer *b = buffer_new(data, len);
	uint64_t v;
	if(buffer_get_string(b, &r->path) != 0) r->path = strdup("");
	buffer_get_varint(b, &v); r->devino.dev = v;
	buffer_get_varint(b, &v); r->devino.ino = v;
	buffer_get_varint(b, &v); r->ts_sec = v;
	buffer_get_varint(b, &v); r->ts_usec = v;
	buffer_get_varint(b, &v); r->te_sec = v;
	buffer_get_varint(b, &v); r->te_usec = v;
	buffer_get_varint(b, &v); r->file_count = v;
	buffer_get_varint(b, &v); r->dir_count = v;
	buffer_get_varint(b, &v); r->size.apparent = v;
	buffer_get_varint(b, &v); r->size.actual = v;
	buffer_get_varint(b, &v); r->size.count = v;
	v = 0; buffer_get_varint(b, &v); r->topn_min = v;
	v = 0; buffer_get_varint(b, &v); r->topn_cnt = v;
	v = 0; buffer_get_varint(b, &v); r->topn_max = v;
	v = 0; buffer_get_varint(b, &v); r->hist_buckets = v;
	r->hist = calloc(r->hist_buckets + 1, sizeof(int64_t));
	for(int64_t i=0; i<r->hist_buckets; i++) {
		v = 0; buffer_get_varint(b, &v); r->hist[i] = v;
	}
	r->topn = calloc(r->topn_cnt + 1, sizeof(struct topn_ent));
	r->topn_n = 0;
	for(int64_t i=0; i<r->topn_cnt; i++) {
		if(b->ptr >= b->len) break;
		uint64_t l;
		char *name = NULL;
		buffer_get_varint(b, &l);
		if(buffer_get_string(b, &name) != 0) break;
		v = 0; buffer_get_varint(b, &v);
		r->topn[r->topn_n].name = name;
		r->topn[r->topn_n].size = v;
		r->topn_n++;
	}
	buffer_free(b);
	return r;
}

struct buffer *report_serialize(struct report *r)
{
	struct buffer *b = buffer_new(NULL, 0);
	buffer_put_string(b, r->path);
