	{ "index", "[options] PATH ...", "Scan the filesystem and generate the Duc index", @INDEX@, opts_index, cmd_index, 0, 1 },
	{ "info", "[options]", "Dump database info", NULL, opts_info, cmd_info, 0, 1 },
