};

static struct cmd *find_cmd(const char *name)
{
	for(struct cmd *c = cmds; c->name; c++) {
		if(strcmp(c->name, name) == 0) return c;
	}
	return NULL;
}

static void print_option_line(struct optdef *o, int with_long)
{
	char buf[256];
	if(o->arg) snprintf(buf, sizeof buf, "%s=VAL", o->name);
	else snprintf(buf, sizeof buf, "%s", o->name);
	if(o->shortopt) printf("  -%c,  --%-20s", o->shortopt, buf);
	else printf("       --%-20s", buf);
	if(with_long && o->descr_long) {
		int pos = strlen(o->descr);
		printf("%s. ", o->descr);
		char *t = strdup(o->descr_long);
		char *save = NULL;
		for(char *w = strtok_r(t, " ", &save); w; w = strtok_r(NULL, " ", &save)) {
			int l = strlen(w);
			if(pos + l > 48) {
				printf("\n%29s", "");
				pos = 0;
			}
			printf("%s ", w);
			pos += l + 1;
		}
		free(t);
		printf("\n");
	} else {
		printf("%s\n", o->descr);
	}
}

static void print_options(struct optdef *opts, int with_long)
{
	for(struct optdef *o = opts; o->name; o++) print_option_line(o, with_long);
}

static void show_cmd_help(struct cmd *c)
{
	printf("usage: duc %s %s\n", c->name, c->usage);
	printf("\n");
	printf("%s.\n", c->descr_short);
	printf("\n");
	printf("Options for the command '%s':\n", c->name);
	print_options(c->opts, 1);
	printf("\n");
	printf("Global options:\n");
	print_options(opts_global, 1);
	if(c->descr_long) {
		printf("\n%s", c->descr_long);
	}
}

static void show_usage(void)
{
	printf("usage: duc <cmd> [options] [args]\n\n");
	printf("Available subcommands:\n\n");
	for(struct cmd *c = cmds; c->name; c++) {
		if(c->hidden) continue;
		printf("  %-10s: %s\n", c->name, c->descr_short);
	}
	printf("\nGlobal options:\n");
	print_options(opts_global, 1);
	printf("\n"
		"Use 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all\n"
		"options and detailed description of the subcommand.\n"
		"\n"
		"Use 'duc help --all' for a complete list of all options for all subcommands.\n");
}

static void show_all(void)
{
	printf("usage: duc <cmd> [options] [args]\n\n");
	printf("Available subcommands:\n\n");
	for(struct cmd *c = cmds; c->name; c++) {
		if(c->hidden) continue;
		printf("duc %s %s: %s\n\n", c->name, c->usage, c->descr_short);
		print_options(c->opts, 0);
		printf("\n");
	}
}

static int cmd_help_fn(struct duc *duc, int argc, char **argv)
{
	(void)duc;
	struct cmd *c = NULL;
	if(argc > 0) c = find_cmd(argv[0]);
	if(c) {
		show_cmd_help(c);
	} else if(g_opt.all) {
		show_all();
	} else {
		show_usage();
	}
	return 0;
}

static void manual_options(struct optdef *opts)
{
	for(struct optdef *o = opts; o->name; o++) {
		printf("  * ");
		if(o->shortopt) printf("`-%c`, ", o->shortopt);
		printf("`--%s%s`:\n", o->name, o->arg ? "=VAL" : "");
		if(o->descr_long) printf("    %s. %s\n\n\n", o->descr, o->descr_long);
		else printf("    %s\n\n", o->descr);
	}
}

static int cmd_manual_fn(struct duc *duc, int argc, char **argv)
{
	(void)duc; (void)argc; (void)argv;
	printf("### Global options\n\n");
	printf("These options apply to all Duc subcommands:\n\n");
	manual_options(opts_global);
	for(struct cmd *c = cmds; c->name; c++) {
		if(c->hidden) continue;
		printf("### duc %s\n\n", c->name);
		if(c->descr_long) printf("%s\n\n", c->descr_long);
		printf("Options for command `duc %s %s`:\n\n", c->name, c->usage);
		manual_options(c->opts);
	}
	return 0;
}

static void show_version(void)
{
	printf("duc version: %s\n", DUC_VERSION);
	printf("options: cairo x11 ui sqlite3\n");
}

/* option handling */

static void opt_apply(struct optdef *o, const char *val)
{
	if(o->type == A_BOOL) {
		*(int *)o->ptr = 1;
	} else if(o->type == A_STR) {
		char **p = o->ptr;
		*p = strdup(val);
	} else if(o->type == A_LIST) {
		char ***p = o->ptr;
		g_opt.exclude_n++;
		*p = realloc(*p, sizeof(char *) * (g_opt.exclude_n + 1));
		(*p)[g_opt.exclude_n - 1] = strdup(val);
		(*p)[g_opt.exclude_n] = NULL;
	}
}

static struct optdef *find_opt_long(struct cmd *c, const char *name)
{
	for(struct optdef *o = opts_global; o->name; o++) if(strcmp(o->name, name) == 0) return o;
	for(struct optdef *o = c->opts; o->name; o++) if(strcmp(o->name, name) == 0) return o;
	return NULL;
}

static void read_config(struct cmd *c, const char *path)
{
	FILE *f = fopen(path, "r");
	if(!f) return;
	char *line = NULL;
	size_t cap = 0;
	char section[256] = "global";
	while(getline(&line, &cap, f) != -1) {
		char *p = line;
		while(*p && isspace((unsigned char)*p)) p++;
		size_t l = strlen(p);
		while(l > 0 && isspace((unsigned char)p[l-1])) p[--l] = 0;
		if(*p == 0 || *p == '#') continue;
		if(*p == '[') {
			char *e = strchr(p, ']');
			if(e) *e = 0;
			snprintf(section, sizeof section, "%s", p + 1);
			continue;
		}
		if(strcmp(section, "global") != 0 && strcmp(section, c->name) != 0) continue;
		char *name = p;
		char *val = NULL;
		char *sp = strchr(p, ' ');
		if(sp) {
			*sp = 0;
			val = sp + 1;
			while(*val == ' ') val++;
		}
		struct optdef *o = find_opt_long(c, name);
		if(!o) {
			fprintf(stderr, "Unknown option '%s'\n", name);
			continue;
		}
		if(o->arg && val == NULL) {
			signal(SIGSEGV, SIG_DFL);
			raise(SIGSEGV);
		}
		opt_apply(o, val);
	}
	free(line);
	fclose(f);
}

static void read_configs(struct cmd *c)
{
	char buf[8192];
	read_config(c, "/etc/ducrc");
	char *home = getenv("HOME");
	char *xdg = getenv("XDG_CONFIG_HOME");
	if(xdg) {
		snprintf(buf, sizeof buf, "%s/duc/ducrc", xdg);
		read_config(c, buf);
	} else if(home) {
		snprintf(buf, sizeof buf, "%s/.config/duc/ducrc", home);
		read_config(c, buf);
	}
	if(home) {
		snprintf(buf, sizeof buf, "%s/.ducrc", home);
		read_config(c, buf);
	}
	read_config(c, "./.ducrc");
}

static int parse_args(struct cmd *c, int *pargc, char ***pargv)
{
	int argc = *pargc;
	char **argv = *pargv;
	int n = 0;
	for(struct optdef *o = opts_global; o->name; o++) n++;
	for(struct optdef *o = c->opts; o->name; o++) n++;
	struct option *lo = calloc(n + 1, sizeof *lo);
	struct optdef **map = calloc(n + 1, sizeof *map);
	char optstr[256];
	int ol = 0;
	int i = 0;
	struct optdef *lists[2] = { opts_global, c->opts };
	for(int k=0; k<2; k++) {
		for(struct optdef *o = lists[k]; o->name; o++) {
			lo[i].name = o->name;
			lo[i].has_arg = o->arg ? required_argument : no_argument;
			lo[i].flag = NULL;
			lo[i].val = o->shortopt ? o->shortopt : 0;
			map[i] = o;
			if(o->shortopt) {
				optstr[ol++] = o->shortopt;
				if(o->arg) optstr[ol++] = ':';
			}
			i++;
		}
	}
	optstr[ol] = 0;
	for(;;) {
		int idx = -1;
		int r = getopt_long(argc, argv, optstr, lo, &idx);
		if(r == -1) break;
		if(r == '?' || r == ':') {
			fprintf(stderr, "Try 'duc --help' for more information.\n");
			exit(1);
		}
		struct optdef *o = NULL;
		if(r == 0 && idx >= 0) {
			o = map[idx];
		} else {
			for(int j=0; j<n; j++) if(map[j]->shortopt == r) { o = map[j]; break; }
		}
		if(o) opt_apply(o, optarg);
	}
	*pargc = argc - optind;
	*pargv = argv + optind;
	free(lo);
	free(map);
	return 0;
}

int main(int argc, char **argv)
{
	g_argv0 = argv[0];
	struct cmd *c = NULL;
	int was_version = 0;
	if(argc >= 2) {
		c = find_cmd(argv[1]);
		if(strcmp(argv[1], "--version") == 0) was_version = 1;
		argv[1] = argv[0];
		argv++;
		argc--;
	}
	if(!c) c = find_cmd("help");

	read_configs(c);
	parse_args(c, &argc, &argv);

	if(g_opt.quiet) g_loglevel = LOG_FTL;
	if(g_opt.verbose) g_loglevel = LOG_INF;
	if(g_opt.debug) g_loglevel = LOG_DBG;

	if(g_opt.version || was_version) {
		show_version();
		return 0;
	}
	if(g_opt.help) {
		show_cmd_help(c);
		return 0;
	}

	struct duc duc;
	memset(&duc, 0, sizeof duc);
	int r = c->fn(&duc, argc, argv);
	fflush(stdout);
	return r;
}
