#include <sys/statvfs.h>
#include <unistd.h>
#include <errno.h>
#include <fnmatch.h>
#include <pwd.h>
#include <limits.h>
#include <mntent.h>

struct ientry {
	char *name;
	int type;
	struct size3 size;
	struct devino devino;
};

struct idir {
	struct ientry *ent;
	size_t n, alloc;
};

struct index_ctx {
	struct duc *duc;
	int dry_run;
	int hide_file_names;
	int check_hard_links;
	int one_fs;
	int progress;
	int bytes;
	int has_uid;
	uid_t uid;
	int max_depth;
	char **exclude;
	char **fs_exclude; int n_fs_exclude;
	char **fs_include; int n_fs_include;
	dev_t root_dev;
	/* hard links */
	struct devino *hl; size_t hl_n, hl_alloc;
	/* stats */
	int64_t files, dirs;
	struct size3 total;
	/* histogram */
	int64_t buckets;
	int64_t *hist;
	/* topn */
	int64_t topn_cnt;
	int64_t topn_slots;
	struct topn_ent *topn;
	/* progress */
	struct timeval last_progress;
	int progress_n;
	/* mounts */
	char **mnt_dir; char **mnt_type; int n_mnt;
};

static int ftype(mode_t m)
{
	if(S_ISBLK(m)) return FT_BLK;
	if(S_ISCHR(m)) return FT_CHR;
	if(S_ISDIR(m)) return FT_DIR;
	if(S_ISFIFO(m)) return FT_FIFO;
	if(S_ISLNK(m)) return FT_LNK;
	if(S_ISREG(m)) return FT_REG;
	if(S_ISSOCK(m)) return FT_SOCK;
	return FT_UNKNOWN;
}

static char **split_list(const char *s, int *n)
{
	*n = 0;
	if(!s) return NULL;
	char *t = strdup(s);
	char **l = NULL;
	char *save = NULL;
	for(char *p = strtok_r(t, ",", &save); p; p = strtok_r(NULL, ",", &save)) {
		l = realloc(l, sizeof(char *) * (*n + 1));
		l[(*n)++] = strdup(p);
	}
	free(t);
	return l;
}

static int in_list(char **l, int n, const char *s)
{
	for(int i=0; i<n; i++) if(strcmp(l[i], s) == 0) return 1;
	return 0;
}

static void read_mounts(struct index_ctx *ctx)
{
	FILE *f = setmntent("/proc/mounts", "r");
	if(!f) f = setmntent("/etc/mtab", "r");
	if(!f) return;
	struct mntent *m;
	while((m = getmntent(f)) != NULL) {
		ctx->mnt_dir = realloc(ctx->mnt_dir, sizeof(char *) * (ctx->n_mnt + 1));
		ctx->mnt_type = realloc(ctx->mnt_type, sizeof(char *) * (ctx->n_mnt + 1));
		ctx->mnt_dir[ctx->n_mnt] = strdup(m->mnt_dir);
		ctx->mnt_type[ctx->n_mnt] = strdup(m->mnt_type);
		ctx->n_mnt++;
	}
	endmntent(f);
}

static const char *fs_type_of(struct index_ctx *ctx, const char *path)
{
	const char *t = NULL;
	for(int i=0; i<ctx->n_mnt; i++) {
		if(strcmp(ctx->mnt_dir[i], path) == 0) t = ctx->mnt_type[i];
	}
	return t;
}

static char *real_path_msg(const char *path, const char *name)
{
	char buf[PATH_MAX];
	buf[0] = 0;
	if(realpath(path, buf) == NULL) {
		duc_log(LOG_WRN, "Cannot determine realpath of: %s", name);
	}
	return strdup(buf);
}

static void show_progress(struct index_ctx *ctx, int final)
{
	struct timeval now;
	gettimeofday(&now, NULL);
	if(!final) {
		long dt = (now.tv_sec - ctx->last_progress.tv_sec) * 1000000L + (now.tv_usec - ctx->last_progress.tv_usec);
		if(dt < 100000) return;
	}
	ctx->last_progress = now;
	char bar[9];
	int p = ctx->progress_n % 14;
	if(p >= 8) p = 14 - p;
	for(int i=0; i<8; i++) bar[i] = (i == p) ? '#' : '-';
	bar[8] = 0;
	ctx->progress_n++;
	char *s = fmt_size(ctx->total.actual, ctx->bytes, 1024);
	char *f = fmt_size(ctx->files, ctx->bytes, 1000);
	char *d = fmt_size(ctx->dirs, ctx->bytes, 1000);
	printf("\033[K[%s] Indexed %sb in %s files and %s directories\r", bar, s, f, d);
	fflush(stdout);
	free(s); free(f); free(d);
}

static void topn_add(struct index_ctx *ctx, const char *path, int64_t size)
{
	if(ctx->topn_slots <= 0) return;
	if(size < DUC_TOPN_MIN_DEFAULT) return;
	if(size <= ctx->topn[0].size) return;
	free(ctx->topn[0].name);
	ctx->topn[0].name = strdup(path);
	ctx->topn[0].size = size;
	for(int64_t i=0; i+1<ctx->topn_slots; i++) {
		if(ctx->topn[i].size > ctx->topn[i+1].size) {
			struct topn_ent t = ctx->topn[i];
			ctx->topn[i] = ctx->topn[i+1];
			ctx->topn[i+1] = t;
		} else break;
	}
}

static void hist_add(struct index_ctx *ctx, int64_t size)
{
	int64_t b = 0;
	uint64_t s = size;
	while(s > 1) { s >>= 1; b++; }
	if(b >= ctx->buckets) {
		duc_log(LOG_WRN, "File sizes large enough we ran out of histogram buckets %jd, please increase the number of buckets and re-run your indexing.", (intmax_t)ctx->buckets);
		return;
	}
	ctx->hist[b]++;
}

static int hl_seen(struct index_ctx *ctx, dev_t dev, ino_t ino)
{
	for(size_t i=0; i<ctx->hl_n; i++) {
		if(ctx->hl[i].dev == (uint64_t)dev && ctx->hl[i].ino == (uint64_t)ino) return 1;
	}
	if(ctx->hl_n >= ctx->hl_alloc) {
		ctx->hl_alloc = ctx->hl_alloc * 2 + 64;
		ctx->hl = realloc(ctx->hl, ctx->hl_alloc * sizeof *ctx->hl);
	}
	ctx->hl[ctx->hl_n].dev = dev;
	ctx->hl[ctx->hl_n].ino = ino;
	ctx->hl_n++;
	return 0;
}

static void write_dir(struct index_ctx *ctx, struct devino *di, struct devino *parent, time_t mtime, struct idir *d)
{
	if(ctx->dry_run) return;
	struct buffer *b = buffer_new(NULL, 0);
	buffer_put_varint(b, parent->dev);
	buffer_put_varint(b, parent->ino);
	buffer_put_varint(b, mtime);
	for(size_t i=0; i<d->n; i++) {
		struct ientry *e = &d->ent[i];
		buffer_put_string(b, e->name);
		buffer_put_varint(b, e->size.apparent);
		buffer_put_varint(b, e->size.actual);
		buffer_put_varint(b, e->size.count);
		buffer_put_varint(b, e->type);
		if(e->type == FT_DIR) {
			buffer_put_varint(b, e->devino.dev);
			buffer_put_varint(b, e->devino.ino);
		}
	}
	char key[64];
	snprintf(key, sizeof key, "%jx/%jx", (uintmax_t)di->dev, (uintmax_t)di->ino);
	db_put(ctx->duc->db, key, strlen(key), b->data, b->len);
	buffer_free(b);
}

static void idir_add(struct idir *d, struct ientry *e)
{
	if(d->n >= d->alloc) {
		d->alloc = d->alloc * 2 + 16;
		d->ent = realloc(d->ent, d->alloc * sizeof *d->ent);
	}
	d->ent[d->n++] = *e;
}

/* Scan directory 'path'. Returns 0 on success, fills size. */
static int scan_dir(struct index_ctx *ctx, const char *path, const char *dname, struct devino *di, struct devino *parent, time_t mtime, int depth, struct size3 *out)
{
	DIR *dir = opendir(path);
	if(!dir) {
		int e = errno;
		char *rp = real_path_msg(path, dname);
		duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
		free(rp);
		return -1;
	}
	duc_log(LOG_DBG, ">> %s", dname);
	struct idir d;
	memset(&d, 0, sizeof d);
	struct size3 total = { 0, 0, 0 };
	struct dirent *de;
	size_t plen = strlen(path);
	while((de = readdir(dir)) != NULL) {
		if(strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
		size_t l = plen + strlen(de->d_name) + 2;
		char *fp = malloc(l);
		if(plen > 0 && path[plen-1] == '/') snprintf(fp, l, "%s%s", path, de->d_name);
		else snprintf(fp, l, "%s/%s", path, de->d_name);
		struct stat st;
		if(lstat(fp, &st) != 0) {
			int e = errno;
			char *rp = real_path_msg(fp, de->d_name);
			duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
			free(rp);
			free(fp);
			continue;
		}
		/* exclude */
		int excluded = 0;
		if(ctx->exclude) {
			for(char **p = ctx->exclude; *p; p++) {
				if(fnmatch(*p, de->d_name, 0) == 0) { excluded = 1; break; }
			}
		}
		if(excluded) {
			char *rp = real_path_msg(fp, de->d_name);
			duc_log(LOG_WRN, "skipping %s: Excluded by user", rp);
			free(rp);
			free(fp);
			continue;
		}
		if(ctx->has_uid && st.st_uid != ctx->uid) {
			free(fp);
			continue;
		}
		int type = ftype(st.st_mode);
		struct ientry e;
		memset(&e, 0, sizeof e);
		e.type = type;
		if(type == FT_DIR) {
			if(st.st_dev != (dev_t)di->dev) {
				if(ctx->one_fs) {
					char *rp = real_path_msg(fp, de->d_name);
					duc_log(LOG_WRN, "skipping %s: Not crossing file system boundaries", rp);
					free(rp);
					free(fp);
					continue;
				}
				if(ctx->n_fs_exclude || ctx->n_fs_include) {
					char *rp = real_path_msg(fp, de->d_name);
					const char *t = fs_type_of(ctx, rp);
					if(t && ctx->n_fs_exclude && in_list(ctx->fs_exclude, ctx->n_fs_exclude, t)) {
						duc_log(LOG_WRN, "skipping %s: File system type '%s' is excluded", rp, t);
						free(rp); free(fp);
						continue;
					}
					if(t && ctx->n_fs_include && !in_list(ctx->fs_include, ctx->n_fs_include, t)) {
						duc_log(LOG_WRN, "skipping %s: File system type '%s' is not included", rp, t);
						free(rp); free(fp);
						continue;
					}
					free(rp);
				}
			}
			struct devino cdi = { st.st_dev, st.st_ino };
			struct size3 cs;
			if(scan_dir(ctx, fp, de->d_name, &cdi, di, st.st_mtime, depth + 1, &cs) != 0) {
				free(fp);
				continue;
			}
			e.name = strdup(de->d_name);
			e.size = cs;
			e.size.count += 1;
			e.devino = cdi;
			ctx->dirs++;
			total.apparent += e.size.apparent;
			total.actual += e.size.actual;
			total.count += e.size.count;
			if(ctx->max_depth == 0 || depth + 1 < ctx->max_depth) {
				idir_add(&d, &e);
			} else {
				free(e.name);
			}
		} else {
			if(ctx->check_hard_links && st.st_nlink > 1) {
				if(hl_seen(ctx, st.st_dev, st.st_ino)) {
					free(fp);
					continue;
				}
			}
			e.size.apparent = st.st_size;
			e.size.actual = (int64_t)st.st_blocks * 512;
			e.size.count = 1;
			e.name = strdup(ctx->hide_file_names ? "<FILE>" : de->d_name);
			duc_log(LOG_DBG, "  %c %jd %jd %s", type_char(type), (intmax_t)e.size.apparent, (intmax_t)e.size.actual, de->d_name);
			ctx->files++;
			ctx->total.apparent += e.size.apparent;
			ctx->total.actual += e.size.actual;
			hist_add(ctx, e.size.apparent);
			topn_add(ctx, fp, e.size.apparent);
			total.apparent += e.size.apparent;
			total.actual += e.size.actual;
			total.count += 1;
			idir_add(&d, &e);
		}
		free(fp);
		if(ctx->progress) show_progress(ctx, 0);
	}
	closedir(dir);
	duc_log(LOG_DBG, "<< %s actual:%jd apparent:%jd", dname, (intmax_t)total.apparent, (intmax_t)total.actual);
	if(ctx->max_depth == 0 || depth < ctx->max_depth) {
		write_dir(ctx, di, parent, mtime, &d);
	}
	for(size_t i=0; i<d.n; i++) free(d.ent[i].name);
	free(d.ent);
	*out = total;
	return 0;
}

static void update_list(struct index_ctx *ctx, struct report *r)
{
	struct db *db = ctx->duc->db;
	size_t len = 0;
	char *list = db_get(db, "duc_index_reports", strlen("duc_index_reports"), &len);
	size_t n = list ? len / DUC_PATH_SLOT : 0;
	size_t idx = n;
	for(size_t i=0; i<n; i++) {
		if(strncmp(list + i * DUC_PATH_SLOT, r->path, DUC_PATH_SLOT) == 0) { idx = i; break; }
	}
	if(idx == n) {
		list = realloc(list, (n + 1) * DUC_PATH_SLOT);
		memset(list + n * DUC_PATH_SLOT, 0, DUC_PATH_SLOT);
		strncpy(list + n * DUC_PATH_SLOT, r->path, DUC_PATH_SLOT - 1);
		n++;
		db_put(db, "duc_index_reports", strlen("duc_index_reports"), list, n * DUC_PATH_SLOT);
	}
	free(list);

	/* histograms */
	size_t hlen = 0;
	char *h = db_get(db, "duc_index_histograms", strlen("duc_index_histograms"), &hlen);
	size_t hn = h ? hlen / DUC_HIST_SLOT : 0;
	if(hn < n) {
		h = realloc(h, n * DUC_HIST_SLOT);
		memset(h + hn * DUC_HIST_SLOT, 0, (n - hn) * DUC_HIST_SLOT);
		hn = n;
	}
	uint64_t *slot = (uint64_t *)(h + idx * DUC_HIST_SLOT);
	memset(slot, 0, DUC_HIST_SLOT);
	for(int64_t i=0; i<r->hist_buckets && i < DUC_HIST_MAX; i++) slot[i] = r->hist[i];
	db_put(db, "duc_index_histograms", strlen("duc_index_histograms"), h, hn * DUC_HIST_SLOT);
	free(h);

	/* topn info */
	const char *tk = "duc_index_topn_info";
	size_t tklen = strlen(tk) + 1;
	size_t tlen = 0;
	char *t = db_get(db, tk, tklen, &tlen);
	size_t tn = t ? tlen / DUC_TOPN_SLOT : 0;
	if(tn < n) {
		t = realloc(t, n * DUC_TOPN_SLOT);
		memset(t + tn * DUC_TOPN_SLOT, 0, (n - tn) * DUC_TOPN_SLOT);
		tn = n;
		db_put(db, tk, tklen, t, tn * DUC_TOPN_SLOT);
	}
	free(t);
}

int cmd_index(struct duc *duc, int argc, char **argv)
{
	if(argc < 1) {
		duc_log(LOG_FTL, "Required index PATH missing.");
		extern void show_cmd_help_by_name(const char *name);
		show_cmd_help_by_name("index");
		return 1;
	}

	struct index_ctx ctx;
	memset(&ctx, 0, sizeof ctx);
	ctx.duc = duc;
	ctx.dry_run = g_opt.dry_run;
	ctx.hide_file_names = g_opt.hide_file_names;
	ctx.check_hard_links = g_opt.check_hard_links;
	ctx.one_fs = g_opt.one_file_system;
	ctx.progress = g_opt.progress;
	ctx.bytes = g_opt.bytes;
	ctx.exclude = g_opt.exclude;
	ctx.max_depth = g_opt.max_depth ? atoi(g_opt.max_depth) : 0;
	ctx.fs_exclude = split_list(g_opt.fs_exclude, &ctx.n_fs_exclude);
	ctx.fs_include = split_list(g_opt.fs_include, &ctx.n_fs_include);
	if(ctx.n_fs_exclude || ctx.n_fs_include) read_mounts(&ctx);

	if(g_opt.uid) {
		int u = atoi(g_opt.uid);
		if(u != 0) { ctx.has_uid = 1; ctx.uid = u; }
	}
	if(g_opt.username) {
		struct passwd *pw = getpwnam(g_opt.username);
		if(!pw) {
			signal(SIGSEGV, SIG_DFL);
			raise(SIGSEGV);
		}
		ctx.has_uid = 1;
		ctx.uid = pw->pw_uid;
	}

	ctx.buckets = DUC_HIST_DEFAULT;
	if(g_opt.buckets) {
		ctx.buckets = atoi(g_opt.buckets);
		if(ctx.buckets > DUC_HIST_MAX) {
			duc_log(LOG_WRN, "Cannot use more than %d histogram buckets.", DUC_HIST_MAX);
		}
	}
	ctx.topn_cnt = DUC_TOPN_DEFAULT;
	if(g_opt.topn) {
		int t = atoi(g_opt.topn);
		if(t < 0) {
			signal(SIGSEGV, SIG_DFL);
			raise(SIGSEGV);
		}
		if(t != 0) ctx.topn_cnt = t;
		if(ctx.topn_cnt > DUC_TOPN_MAX) {
			duc_log(LOG_WRN, "Cannot store more than %d topN files", DUC_TOPN_MAX);
		}
	}

	/* check file systems */
	int big = 0;
	for(int i=0; i<argc; i++) {
		struct statvfs sv;
		if(statvfs(argv[i], &sv) != 0) {
			duc_log(LOG_FTL, "Can't run statvfs on %s", argv[i]);
			return 1;
		}
		if(sv.f_files - sv.f_ffree > 1000000) big = 1;
	}
	if(big) duc_log(LOG_INF, "Found big filesystem");

	char *dbpath = g_opt.database ? strdup(g_opt.database) : duc_default_db_path();
	if(dbpath) duc_log(LOG_INF, "Writing to database \"%s\"", dbpath);
	if(duc_open(duc, dbpath, 1) != 0) {
		duc_log(LOG_FTL, "%s", duc_strerror(duc->err));
		return 1;
	}

	for(int i=0; i<argc; i++) {
		char *path = path_normalize(argv[i]);
		struct report r;
		memset(&r, 0, sizeof r);
		r.path = path;
		ctx.files = 0; ctx.dirs = 0;
		memset(&ctx.total, 0, sizeof ctx.total);
		ctx.hist = calloc(ctx.buckets > 0 ? ctx.buckets : 1, sizeof(int64_t));
		ctx.topn_slots = ctx.topn_cnt < DUC_TOPN_MAX ? ctx.topn_cnt : DUC_TOPN_MAX;
		ctx.topn = calloc(ctx.topn_slots + 1, sizeof(struct topn_ent));
		ctx.hl_n = 0;
		ctx.progress_n = 0;
		memset(&ctx.last_progress, 0, sizeof ctx.last_progress);
		struct timeval ts, te;
		gettimeofday(&ts, NULL);
		gettimeofday(&ctx.last_progress, NULL);

		struct stat st;
		struct size3 sz = { 0, 0, 0 };
		int ok = 0;
		if(lstat(path, &st) == 0) {
			struct devino di = { st.st_dev, st.st_ino };
			struct devino parent = { 0, 0 };
			ctx.root_dev = st.st_dev;
			if(scan_dir(&ctx, path, path, &di, &parent, st.st_mtime, 0, &sz) == 0) {
				ok = 1;
				r.devino = di;
			}
		} else {
			int e = errno;
			char *rp = real_path_msg(path, path);
			duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
			free(rp);
		}
		if(ok) {
			ctx.dirs++;
			sz.count += 1;
		}
		gettimeofday(&te, NULL);
		r.ts_sec = ts.tv_sec; r.ts_usec = ts.tv_usec;
		r.te_sec = te.tv_sec; r.te_usec = te.tv_usec;
		r.file_count = ctx.files;
		r.dir_count = ctx.dirs;
		r.size.apparent = sz.apparent;
		r.size.actual = sz.actual;
		r.size.count = ok ? sz.count : 0;
		r.topn_min = DUC_TOPN_MIN_DEFAULT;
		r.topn_cnt = ctx.topn_cnt;
		r.topn_max = DUC_TOPN_MAX;
		r.hist_buckets = ctx.buckets;
		r.hist = ctx.hist;
		r.topn = ctx.topn;
		r.topn_n = ctx.topn_slots;

		if(ctx.progress) {
			show_progress(&ctx, 1);
			printf("\n");
			fflush(stdout);
		}

		if(!ctx.dry_run) {
			struct buffer *b = report_serialize(&r);
			db_put(duc->db, path, strlen(path), b->data, b->len);
			buffer_free(b);
			update_list(&ctx, &r);
		}

		char *sa = fmt_size(r.size.apparent, ctx.bytes, 1024);
		char *sc = fmt_size(r.size.actual, ctx.bytes, 1024);
		double secs = (te.tv_sec - ts.tv_sec) + (te.tv_usec - ts.tv_usec) / 1e6;
		duc_log(LOG_INF, "Indexed %jd files and %jd directories, (%sB apparent, %sB actual) in %.2f secs.",
				(intmax_t)r.file_count, (intmax_t)r.dir_count, sa, sc, secs);
		free(sa); free(sc);

		free(ctx.hist);
		for(int64_t k=0; k<ctx.topn_slots; k++) free(ctx.topn[k].name);
		free(ctx.topn);
		free(path);
	}

	duc_close(duc);
	return 0;
}
EOF
grep -n "signal" index.c | head -3; sed -i 's/#include <mntent.h>/#include <mntent.h>\n#include <signal.h>/' index.c"}

actions.command:
cd /workspace/src && cat > index.c <<'EOF'
#include "duc.h"
#include <dirent.h>
#include <sys/stat.h>
#include <sys/statvfs.h>
#include <unistd.h>
#include <errno.h>
#include <fnmatch.h>
#include <pwd.h>
#include <limits.h>
#include <mntent.h>

struct ientry {
	char *name;
	int type;
	struct size3 size;
	struct devino devino;
};

struct idir {
	struct ientry *ent;
	size_t n, alloc;
};

struct index_ctx {
	struct duc *duc;
	int dry_run;
	int hide_file_names;
	int check_hard_links;
	int one_fs;
	int progress;
	int bytes;
	int has_uid;
	uid_t uid;
	int max_depth;
	char **exclude;
	char **fs_exclude; int n_fs_exclude;
	char **fs_include; int n_fs_include;
	dev_t root_dev;
	/* hard links */
	struct devino *hl; size_t hl_n, hl_alloc;
	/* stats */
	int64_t files, dirs;
	struct size3 total;
	/* histogram */
	int64_t buckets;
	int64_t *hist;
	/* topn */
	int64_t topn_cnt;
	int64_t topn_slots;
	struct topn_ent *topn;
	/* progress */
	struct timeval last_progress;
	int progress_n;
	/* mounts */
	char **mnt_dir; char **mnt_type; int n_mnt;
};

static int ftype(mode_t m)
{
	if(S_ISBLK(m)) return FT_BLK;
	if(S_ISCHR(m)) return FT_CHR;
	if(S_ISDIR(m)) return FT_DIR;
	if(S_ISFIFO(m)) return FT_FIFO;
	if(S_ISLNK(m)) return FT_LNK;
	if(S_ISREG(m)) return FT_REG;
	if(S_ISSOCK(m)) return FT_SOCK;
	return FT_UNKNOWN;
}

static char **split_list(const char *s, int *n)
{
	*n = 0;
	if(!s) return NULL;
	char *t = strdup(s);
	char **l = NULL;
	char *save = NULL;
	for(char *p = strtok_r(t, ",", &save); p; p = strtok_r(NULL, ",", &save)) {
		l = realloc(l, sizeof(char *) * (*n + 1));
		l[(*n)++] = strdup(p);
	}
	free(t);
	return l;
}

static int in_list(char **l, int n, const char *s)
{
	for(int i=0; i<n; i++) if(strcmp(l[i], s) == 0) return 1;
	return 0;
}

static void read_mounts(struct index_ctx *ctx)
{
	FILE *f = setmntent("/proc/mounts", "r");
	if(!f) f = setmntent("/etc/mtab", "r");
	if(!f) return;
	struct mntent *m;
	while((m = getmntent(f)) != NULL) {
		ctx->mnt_dir = realloc(ctx->mnt_dir, sizeof(char *) * (ctx->n_mnt + 1));
		ctx->mnt_type = realloc(ctx->mnt_type, sizeof(char *) * (ctx->n_mnt + 1));
		ctx->mnt_dir[ctx->n_mnt] = strdup(m->mnt_dir);
		ctx->mnt_type[ctx->n_mnt] = strdup(m->mnt_type);
		ctx->n_mnt++;
	}
	endmntent(f);
}

static const char *fs_type_of(struct index_ctx *ctx, const char *path)
{
	const char *t = NULL;
	for(int i=0; i<ctx->n_mnt; i++) {
		if(strcmp(ctx->mnt_dir[i], path) == 0) t = ctx->mnt_type[i];
	}
	return t;
}

static char *real_path_msg(const char *path, const char *name)
{
	char buf[PATH_MAX];
	buf[0] = 0;
	if(realpath(path, buf) == NULL) {
		duc_log(LOG_WRN, "Cannot determine realpath of: %s", name);
	}
	return strdup(buf);
}

static void show_progress(struct index_ctx *ctx, int final)
{
	struct timeval now;
	gettimeofday(&now, NULL);
	if(!final) {
		long dt = (now.tv_sec - ctx->last_progress.tv_sec) * 1000000L + (now.tv_usec - ctx->last_progress.tv_usec);
		if(dt < 100000) return;
	}
	ctx->last_progress = now;
	char bar[9];
	int p = ctx->progress_n % 14;
	if(p >= 8) p = 14 - p;
	for(int i=0; i<8; i++) bar[i] = (i == p) ? '#' : '-';
	bar[8] = 0;
	ctx->progress_n++;
	char *s = fmt_size(ctx->total.actual, ctx->bytes, 1024);
	char *f = fmt_size(ctx->files, ctx->bytes, 1000);
	char *d = fmt_size(ctx->dirs, ctx->bytes, 1000);
	printf("\033[K[%s] Indexed %sb in %s files and %s directories\r", bar, s, f, d);
	fflush(stdout);
	free(s); free(f); free(d);
}

static void topn_add(struct index_ctx *ctx, const char *path, int64_t size)
{
	if(ctx->topn_slots <= 0) return;
	if(size < DUC_TOPN_MIN_DEFAULT) return;
	if(size <= ctx->topn[0].size) return;
	free(ctx->topn[0].name);
	ctx->topn[0].name = strdup(path);
	ctx->topn[0].size = size;
	for(int64_t i=0; i+1<ctx->topn_slots; i++) {
		if(ctx->topn[i].size > ctx->topn[i+1].size) {
			struct topn_ent t = ctx->topn[i];
			ctx->topn[i] = ctx->topn[i+1];
			ctx->topn[i+1] = t;
		} else break;
	}
}

static void hist_add(struct index_ctx *ctx, int64_t size)
{
	int64_t b = 0;
	uint64_t s = size;
	while(s > 1) { s >>= 1; b++; }
	if(b >= ctx->buckets) {
		duc_log(LOG_WRN, "File sizes large enough we ran out of histogram buckets %jd, please increase the number of buckets and re-run your indexing.", (intmax_t)ctx->buckets);
		return;
	}
	ctx->hist[b]++;
}

static int hl_seen(struct index_ctx *ctx, dev_t dev, ino_t ino)
{
	for(size_t i=0; i<ctx->hl_n; i++) {
		if(ctx->hl[i].dev == (uint64_t)dev && ctx->hl[i].ino == (uint64_t)ino) return 1;
	}
	if(ctx->hl_n >= ctx->hl_alloc) {
		ctx->hl_alloc = ctx->hl_alloc * 2 + 64;
		ctx->hl = realloc(ctx->hl, ctx->hl_alloc * sizeof *ctx->hl);
	}
	ctx->hl[ctx->hl_n].dev = dev;
	ctx->hl[ctx->hl_n].ino = ino;
	ctx->hl_n++;
	return 0;
}

static void write_dir(struct index_ctx *ctx, struct devino *di, struct devino *parent, time_t mtime, struct idir *d)
{
	if(ctx->dry_run) return;
	struct buffer *b = buffer_new(NULL, 0);
	buffer_put_varint(b, parent->dev);
	buffer_put_varint(b, parent->ino);
	buffer_put_varint(b, mtime);
	for(size_t i=0; i<d->n; i++) {
		struct ientry *e = &d->ent[i];
		buffer_put_string(b, e->name);
		buffer_put_varint(b, e->size.apparent);
		buffer_put_varint(b, e->size.actual);
		buffer_put_varint(b, e->size.count);
		buffer_put_varint(b, e->type);
		if(e->type == FT_DIR) {
			buffer_put_varint(b, e->devino.dev);
			buffer_put_varint(b, e->devino.ino);
		}
	}
	char key[64];
	snprintf(key, sizeof key, "%jx/%jx", (uintmax_t)di->dev, (uintmax_t)di->ino);
	db_put(ctx->duc->db, key, strlen(key), b->data, b->len);
	buffer_free(b);
}

static void idir_add(struct idir *d, struct ientry *e)
{
	if(d->n >= d->alloc) {
		d->alloc = d->alloc * 2 + 16;
		d->ent = realloc(d->ent, d->alloc * sizeof *d->ent);
	}
	d->ent[d->n++] = *e;
}

/* Scan directory 'path'. Returns 0 on success, fills size. */
static int scan_dir(struct index_ctx *ctx, const char *path, const char *dname, struct devino *di, struct devino *parent, time_t mtime, int depth, struct size3 *out)
{
	DIR *dir = opendir(path);
	if(!dir) {
		int e = errno;
		char *rp = real_path_msg(path, dname);
		duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
		free(rp);
		return -1;
	}
	duc_log(LOG_DBG, ">> %s", dname);
	struct idir d;
	memset(&d, 0, sizeof d);
	struct size3 total = { 0, 0, 0 };
	struct dirent *de;
	size_t plen = strlen(path);
	while((de = readdir(dir)) != NULL) {
		if(strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
		size_t l = plen + strlen(de->d_name) + 2;
		char *fp = malloc(l);
		if(plen > 0 && path[plen-1] == '/') snprintf(fp, l, "%s%s", path, de->d_name);
		else snprintf(fp, l, "%s/%s", path, de->d_name);
		struct stat st;
		if(lstat(fp, &st) != 0) {
			int e = errno;
			char *rp = real_path_msg(fp, de->d_name);
			duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
			free(rp);
			free(fp);
			continue;
		}
		/* exclude */
		int excluded = 0;
		if(ctx->exclude) {
			for(char **p = ctx->exclude; *p; p++) {
				if(fnmatch(*p, de->d_name, 0) == 0) { excluded = 1; break; }
			}
		}
		if(excluded) {
			char *rp = real_path_msg(fp, de->d_name);
			duc_log(LOG_WRN, "skipping %s: Excluded by user", rp);
			free(rp);
			free(fp);
			continue;
		}
		if(ctx->has_uid && st.st_uid != ctx->uid) {
			free(fp);
			continue;
		}
		int type = ftype(st.st_mode);
		struct ientry e;
		memset(&e, 0, sizeof e);
		e.type = type;
		if(type == FT_DIR) {
			if(st.st_dev != (dev_t)di->dev) {
				if(ctx->one_fs) {
					char *rp = real_path_msg(fp, de->d_name);
					duc_log(LOG_WRN, "skipping %s: Not crossing file system boundaries", rp);
					free(rp);
					free(fp);
					continue;
				}
				if(ctx->n_fs_exclude || ctx->n_fs_include) {
					char *rp = real_path_msg(fp, de->d_name);
					const char *t = fs_type_of(ctx, rp);
					if(t && ctx->n_fs_exclude && in_list(ctx->fs_exclude, ctx->n_fs_exclude, t)) {
						duc_log(LOG_WRN, "skipping %s: File system type '%s' is excluded", rp, t);
						free(rp); free(fp);
						continue;
					}
					if(t && ctx->n_fs_include && !in_list(ctx->fs_include, ctx->n_fs_include, t)) {
						duc_log(LOG_WRN, "skipping %s: File system type '%s' is not included", rp, t);
						free(rp); free(fp);
						continue;
					}
					free(rp);
				}
			}
			struct devino cdi = { st.st_dev, st.st_ino };
			struct size3 cs;
			if(scan_dir(ctx, fp, de->d_name, &cdi, di, st.st_mtime, depth + 1, &cs) != 0) {
				free(fp);
				continue;
			}
			e.name = strdup(de->d_name);
			e.size = cs;
			e.size.count += 1;
			e.devino = cdi;
			ctx->dirs++;
			total.apparent += e.size.apparent;
			total.actual += e.size.actual;
			total.count += e.size.count;
			if(ctx->max_depth == 0 || depth + 1 < ctx->max_depth) {
				idir_add(&d, &e);
			} else {
				free(e.name);
			}
		} else {
			if(ctx->check_hard_links && st.st_nlink > 1) {
				if(hl_seen(ctx, st.st_dev, st.st_ino)) {
					free(fp);
					continue;
				}
			}
			e.size.apparent = st.st_size;
			e.size.actual = (int64_t)st.st_blocks * 512;
			e.size.count = 1;
			e.name = strdup(ctx->hide_file_names ? "<FILE>" : de->d_name);
			duc_log(LOG_DBG, "  %c %jd %jd %s", type_char(type), (intmax_t)e.size.apparent, (intmax_t)e.size.actual, de->d_name);
			ctx->files++;
			ctx->total.apparent += e.size.apparent;
			ctx->total.actual += e.size.actual;
			hist_add(ctx, e.size.apparent);
			topn_add(ctx, fp, e.size.apparent);
			total.apparent += e.size.apparent;
			total.actual += e.size.actual;
			total.count += 1;
			idir_add(&d, &e);
		}
		free(fp);
		if(ctx->progress) show_progress(ctx, 0);
	}
	closedir(dir);
	duc_log(LOG_DBG, "<< %s actual:%jd apparent:%jd", dname, (intmax_t)total.apparent, (intmax_t)total.actual);
	if(ctx->max_depth == 0 || depth < ctx->max_depth) {
		write_dir(ctx, di, parent, mtime, &d);
	}
	for(size_t i=0; i<d.n; i++) free(d.ent[i].name);
	free(d.ent);
	*out = total;
	return 0;
}

static void update_list(struct index_ctx *ctx, struct report *r)
{
	struct db *db = ctx->duc->db;
	size_t len = 0;
	char *list = db_get(db, "duc_index_reports", strlen("duc_index_reports"), &len);
	size_t n = list ? len / DUC_PATH_SLOT : 0;
	size_t idx = n;
	for(size_t i=0; i<n; i++) {
		if(strncmp(list + i * DUC_PATH_SLOT, r->path, DUC_PATH_SLOT) == 0) { idx = i; break; }
	}
	if(idx == n) {
		list = realloc(list, (n + 1) * DUC_PATH_SLOT);
		memset(list + n * DUC_PATH_SLOT, 0, DUC_PATH_SLOT);
		strncpy(list + n * DUC_PATH_SLOT, r->path, DUC_PATH_SLOT - 1);
		n++;
		db_put(db, "duc_index_reports", strlen("duc_index_reports"), list, n * DUC_PATH_SLOT);
	}
	free(list);

	/* histograms */
	size_t hlen = 0;
	char *h = db_get(db, "duc_index_histograms", strlen("duc_index_histograms"), &hlen);
	size_t hn = h ? hlen / DUC_HIST_SLOT : 0;
	if(hn < n) {
		h = realloc(h, n * DUC_HIST_SLOT);
		memset(h + hn * DUC_HIST_SLOT, 0, (n - hn) * DUC_HIST_SLOT);
		hn = n;
	}
	uint64_t *slot = (uint64_t *)(h + idx * DUC_HIST_SLOT);
	memset(slot, 0, DUC_HIST_SLOT);
	for(int64_t i=0; i<r->hist_buckets && i < DUC_HIST_MAX; i++) slot[i] = r->hist[i];
	db_put(db, "duc_index_histograms", strlen("duc_index_histograms"), h, hn * DUC_HIST_SLOT);
	free(h);

	/* topn info */
	const char *tk = "duc_index_topn_info";
	size_t tklen = strlen(tk) + 1;
	size_t tlen = 0;
	char *t = db_get(db, tk, tklen, &tlen);
	size_t tn = t ? tlen / DUC_TOPN_SLOT : 0;
	if(tn < n) {
		t = realloc(t, n * DUC_TOPN_SLOT);
		memset(t + tn * DUC_TOPN_SLOT, 0, (n - tn) * DUC_TOPN_SLOT);
		tn = n;
		db_put(db, tk, tklen, t, tn * DUC_TOPN_SLOT);
	}
	free(t);
}

int cmd_index(struct duc *duc, int argc, char **argv)
{
	if(argc < 1) {
		duc_log(LOG_FTL, "Required index PATH missing.");
		extern void show_cmd_help_by_name(const char *name);
		show_cmd_help_by_name("index");
		return 1;
	}

	struct index_ctx ctx;
	memset(&ctx, 0, sizeof ctx);
	ctx.duc = duc;
	ctx.dry_run = g_opt.dry_run;
	ctx.hide_file_names = g_opt.hide_file_names;
	ctx.check_hard_links = g_opt.check_hard_links;
	ctx.one_fs = g_opt.one_file_system;
	ctx.progress = g_opt.progress;
	ctx.bytes = g_opt.bytes;
	ctx.exclude = g_opt.exclude;
	ctx.max_depth = g_opt.max_depth ? atoi(g_opt.max_depth) : 0;
	ctx.fs_exclude = split_list(g_opt.fs_exclude, &ctx.n_fs_exclude);
	ctx.fs_include = split_list(g_opt.fs_include, &ctx.n_fs_include);
	if(ctx.n_fs_exclude || ctx.n_fs_include) read_mounts(&ctx);

	if(g_opt.uid) {
		int u = atoi(g_opt.uid);
		if(u != 0) { ctx.has_uid = 1; ctx.uid = u; }
	}
	if(g_opt.username) {
		struct passwd *pw = getpwnam(g_opt.username);
		if(!pw) {
			signal(SIGSEGV, SIG_DFL);
			raise(SIGSEGV);
		}
		ctx.has_uid = 1;
		ctx.uid = pw->pw_uid;
	}

	ctx.buckets = DUC_HIST_DEFAULT;
	if(g_opt.buckets) {
		ctx.buckets = atoi(g_opt.buckets);
		if(ctx.buckets > DUC_HIST_MAX) {
			duc_log(LOG_WRN, "Cannot use more than %d histogram buckets.", DUC_HIST_MAX);
		}
	}
	ctx.topn_cnt = DUC_TOPN_DEFAULT;
	if(g_opt.topn) {
		int t = atoi(g_opt.topn);
		if(t < 0) {
			signal(SIGSEGV, SIG_DFL);
			raise(SIGSEGV);
		}
		if(t != 0) ctx.topn_cnt = t;
		if(ctx.topn_cnt > DUC_TOPN_MAX) {
			duc_log(LOG_WRN, "Cannot store more than %d topN files", DUC_TOPN_MAX);
		}
	}

	/* check file systems */
	int big = 0;
	for(int i=0; i<argc; i++) {
		struct statvfs sv;
		if(statvfs(argv[i], &sv) != 0) {
			duc_log(LOG_FTL, "Can't run statvfs on %s", argv[i]);
			return 1;
		}
		if(sv.f_files - sv.f_ffree > 1000000) big = 1;
	}
	if(big) duc_log(LOG_INF, "Found big filesystem");

	char *dbpath = g_opt.database ? strdup(g_opt.database) : duc_default_db_path();
	if(dbpath) duc_log(LOG_INF, "Writing to database \"%s\"", dbpath);
	if(duc_open(duc, dbpath, 1) != 0) {
		duc_log(LOG_FTL, "%s", duc_strerror(duc->err));
		return 1;
	}

	for(int i=0; i<argc; i++) {
		char *path = path_normalize(argv[i]);
		struct report r;
		memset(&r, 0, sizeof r);
		r.path = path;
		ctx.files = 0; ctx.dirs = 0;
		memset(&ctx.total, 0, sizeof ctx.total);
		ctx.hist = calloc(ctx.buckets > 0 ? ctx.buckets : 1, sizeof(int64_t));
		ctx.topn_slots = ctx.topn_cnt < DUC_TOPN_MAX ? ctx.topn_cnt : DUC_TOPN_MAX;
		ctx.topn = calloc(ctx.topn_slots + 1, sizeof(struct topn_ent));
		ctx.hl_n = 0;
		ctx.progress_n = 0;
		memset(&ctx.last_progress, 0, sizeof ctx.last_progress);
		struct timeval ts, te;
		gettimeofday(&ts, NULL);
		gettimeofday(&ctx.last_progress, NULL);

		struct stat st;
		struct size3 sz = { 0, 0, 0 };
		int ok = 0;
		if(lstat(path, &st) == 0) {
			struct devino di = { st.st_dev, st.st_ino };
			struct devino parent = { 0, 0 };
			ctx.root_dev = st.st_dev;
			if(scan_dir(&ctx, path, path, &di, &parent, st.st_mtime, 0, &sz) == 0) {
				ok = 1;
				r.devino = di;
			}
		} else {
			int e = errno;
			char *rp = real_path_msg(path, path);
			duc_log(LOG_WRN, "skipping %s: %s", rp, strerror(e));
			free(rp);
		}
		if(ok) {
			ctx.dirs++;
			sz.count += 1;
		}
		gettimeofday(&te, NULL);
		r.ts_sec = ts.tv_sec; r.ts_usec = ts.tv_usec;
		r.te_sec = te.tv_sec; r.te_usec = te.tv_usec;
		r.file_count = ctx.files;
		r.dir_count = ctx.dirs;
		r.size.apparent = sz.apparent;
		r.size.actual = sz.actual;
		r.size.count = ok ? sz.count : 0;
		r.topn_min = DUC_TOPN_MIN_DEFAULT;
		r.topn_cnt = ctx.topn_cnt;
		r.topn_max = DUC_TOPN_MAX;
		r.hist_buckets = ctx.buckets;
		r.hist = ctx.hist;
		r.topn = ctx.topn;
		r.topn_n = ctx.topn_slots;

		if(ctx.progress) {
			show_progress(&ctx, 1);
			printf("\n");
			fflush(stdout);
		}

		if(!ctx.dry_run) {
			struct buffer *b = report_serialize(&r);
			db_put(duc->db, path, strlen(path), b->data, b->len);
			buffer_free(b);
			update_list(&ctx, &r);
		}

		char *sa = fmt_size(r.size.apparent, ctx.bytes, 1024);
		char *sc = fmt_size(r.size.actual, ctx.bytes, 1024);
		double secs = (te.tv_sec - ts.tv_sec) + (te.tv_usec - ts.tv_usec) / 1e6;
		duc_log(LOG_INF, "Indexed %jd files and %jd directories, (%sB apparent, %sB actual) in %.2f secs.",
				(intmax_t)r.file_count, (intmax_t)r.dir_count, sa, sc, secs);
		free(sa); free(sc);

		free(ctx.hist);
		for(int64_t k=0; k<ctx.topn_slots; k++) free(ctx.topn[k].name);
		free(ctx.topn);
		free(path);
	}

	duc_close(duc);
	return 0;
}
