static const char *tree_ascii[] = { "`+-", " |-", " `-", " |  ", "    " };

static const char *color_reset = "\033[0m";
static const char *color_red = "\033[31m";
static const char *color_yellow = "\033[33m";

static void print_size(int64_t v, int width)
{
	char *s = fmt_size_st(v, g_opt.bytes, st_type);
	printf("%*s", width, s);
	free(s);
}

static void ls_one(struct duc *duc, struct ddir *dir, int level, char *tree_prefix, const char *relpath)
{
	const char **tree = g_opt.ascii ? tree_ascii : tree_utf8;
	ddir_sort(dir, st_type, g_opt.name_sort ? SORT_NAME : SORT_SIZE);

	size_t max_name_len = 0;
	int64_t max_size = 0;
	size_t count = 0;
	for(size_t i=0; i<dir->ent_count; i++) {
		struct dirent_d *e = &dir->ent[i];
		if(g_opt.dirs_only && e->type != FT_DIR) continue;
		size_t l = strlen(e->name);
		if(l > max_name_len) max_name_len = l;
		int64_t s = size_get(&e->size, st_type);
		if(s > max_size) max_size = s;
		count++;
	}
	if(g_opt.classify) max_name_len++;

	int size_len = g_opt.bytes ? 12 : 6;
	int bar_width = ls_width - 9 - size_len - (int)max_name_len - (g_opt.recursive ? level * 4 : 0);

	size_t n = 0;
	for(size_t i=0; i<dir->ent_count; i++) {
		struct dirent_d *e = &dir->ent[i];
		if(g_opt.dirs_only && e->type != FT_DIR) continue;
		int first = (n == 0);
		int last = (n == count - 1);
		n++;
		int64_t s = size_get(&e->size, st_type);

		print_size(s, size_len);
		putchar(' ');

		char *child_rel = NULL;
		if(g_opt.recursive && g_opt.full_path) {
			size_t l = strlen(relpath) + strlen(e->name) + 2;
			child_rel = malloc(l);
			if(relpath[0]) snprintf(child_rel, l, "%s/%s", relpath, e->name);
			else snprintf(child_rel, l, "%s", e->name);
			printf("%s", child_rel);
			if(g_opt.classify) putchar(type_char(e->type));
		} else {
			if(g_opt.recursive) {
				printf("%s", tree_prefix);
				if(first && !last) printf("%s", tree[0]);
				else if(last) printf("%s", tree[2]);
				else printf("%s", tree[1]);
				putchar(' ');
			}
			if(use_color && e->type == FT_DIR) printf("%s", color_red);
			printf("%s", e->name);
			if(use_color && e->type == FT_DIR) printf("%s", color_reset);
			if(g_opt.classify) putchar(type_char(e->type));
			if(g_opt.graph) {
				size_t l = strlen(e->name) + (g_opt.classify ? 1 : 0);
				for(size_t k=l; k<max_name_len; k++) putchar(' ');
				printf(" [");
				if(use_color) printf("%s", color_yellow);
				int w = 0;
				if(bar_width > 0 && max_size > 0) {
					w = (int)((__int128)s * bar_width / max_size);
				}
				for(int k=0; k<bar_width; k++) putchar(k < w ? '+' : ' ');
				if(use_color) printf("%s", color_reset);
				putchar(']');
			}
		}
		putchar('\n');

		if(g_opt.recursive && level < ls_levels && e->type == FT_DIR) {
			struct ddir *child = ddir_openent(duc, dir, e);
			if(child) {
				size_t pl = strlen(tree_prefix);
				char *np = malloc(pl + 16);
				memcpy(np, tree_prefix, pl);
				strcpy(np + pl, last ? tree[4] : tree[3]);
				ls_one(duc, child, level + 1, np, child_rel ? child_rel : "");
				free(np);
				ddir_free(child);
			}
		}
		free(child_rel);
	}
}

