	if(cols) {
		ls_width = atoi(cols);
	}
	if(isatty(STDOUT_FILENO)) {
		struct winsize w;
		if(ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) == 0) ls_width = w.ws_col;
		if(g_opt.color) use_color = 1;
	}

	if(open_db_read(duc, 0) != 0) return 1;

	char *def[] = { ".", NULL };
	if(argc == 0) {
		argc = 1;
		argv = def;
	}
	for(int i=0; i<argc; i++) {
		struct ddir *dir = ddir_open(duc, argv[i]);
		if(!dir) {
			fprintf(stderr, "The requested path '%s' was not found in the database,\n", argv[i]);
			fprintf(stderr, "Please run 'duc info' for a list of available directories.\n");
