		char *files = fmt_size(r->file_count, g_opt.bytes, 1000);
		char *dirs = fmt_size(r->dir_count, g_opt.bytes, 1000);
		char *size = fmt_size(g_opt.apparent ? r->size.apparent : r->size.actual, g_opt.bytes, 1024);
		printf("%s %s %7s %7s %7s %s\n", date, tim, files, dirs, size, r->path);
		free(files); free(dirs); free(size);
		if(g_opt.histogram) {
			printf("\nHistogram:\n----------\n");
			for(int64_t k=0; k<r->hist_buckets; k++) {
				if(r->hist[k] > 0) printf("2^%-4jd%jd\n", (intmax_t)k, (intmax_t)r->hist[k]);
			}
		}
		report_free(r);
	}
	for(size_t i=0; i<n; i++) free(list[i]);
	free(list);
	duc_close(duc);
	return 0;
}

