{
	(void)argc; (void)argv;
	if(open_db_read(duc, 1) != 0) return 1;
	char **list; size_t n;
	report_get_list(duc, &list, &n);
	for(size_t i=0; i<n; i++) {
		struct report *r = report_load(duc, list[i]);
		if(!r) continue;
		printf("Path: %s\n", r->path);
		printf("Bkt       Size      Count\n");
		for(int64_t k=0; k<r->hist_buckets; k++) {
			double v = 1;
			for(int64_t j=0; j<k; j++) v *= 2;
			char *s = human_size(v, 1024);
			printf("%3jd %10s %10jd\n", (intmax_t)k, s, (intmax_t)r->hist[k]);
			free(s);
		}
		printf("\n");
		report_free(r);
	}
	for(size_t i=0; i<n; i++) free(list[i]);
	free(list);
	duc_close(duc);
	return 0;
}

