/* XML */

static void xml_escape(const char *s)
{
	for(; *s; s++) {
		switch(*s) {
			case '<': fputs("&lt;", stdout); break;
			case '>': fputs("&gt;", stdout); break;
			case '&': fputs("&amp;", stdout); break;
			case '"': fputs("&quot;", stdout); break;
			case '\'': fputs("&apos;", stdout); break;
			default: putchar(*s);
		}
	}
}

static int64_t g_min_size;
static int g_ex_files;
static int g_st;

static void xml_dump(struct duc *duc, struct ddir *dir, int depth)
{
	ddir_sort(dir, ST_ACTUAL, SORT_SIZE);
	for(size_t i=0; i<dir->ent_count; i++) {
		struct dirent_d *e = &dir->ent[i];
		if(g_ex_files && e->type != FT_DIR) continue;
		if(size_get(&e->size, g_st) < g_min_size) continue;
		printf("%*s", depth, "");
		if(e->type == FT_DIR) {
			printf("<ent type=\"dir\" name=\"");
			xml_escape(e->name);
			printf("\" size_apparent=\"%jd\" size_actual=\"%jd\" count=\"%jd\">\n",
				(intmax_t)e->size.apparent, (intmax_t)e->size.actual, (intmax_t)e->size.count);
			struct ddir *child = ddir_openent(duc, dir, e);
			if(child) {
				xml_dump(duc, child, depth + 1);
				ddir_free(child);
			}
			printf("%*s</ent>\n", depth, "");
		} else {
			printf("<ent name=\"");
			xml_escape(e->name);
			printf("\" size_apparent=\"%jd\" size_actual=\"%jd\" />\n",
				(intmax_t)e->size.apparent, (intmax_t)e->size.actual);
		}
	}
}

int cmd_xml(struct duc *duc, int argc, char **argv)
{
	g_min_size = g_opt.min_size ? atoll(g_opt.min_size) : 0;
	g_ex_files = g_opt.exclude_files;
	g_st = g_opt.apparent ? ST_APPARENT : ST_ACTUAL;
	if(open_db_read(duc, 1) != 0) return 1;
	const char *path = argc > 0 ? argv[0] : ".";
	struct ddir *dir = ddir_open(duc, path);
	if(!dir) {
		duc_log(LOG_FTL, "%s", duc_strerror(duc->err));
		duc_close(duc);
		return 1;
	}
	printf("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
	printf("<duc root=\"");
	xml_escape(dir->path);
	printf("\" size_apparent=\"%jd\" size_actual=\"%jd\" count=\"%jd\">\n",
		(intmax_t)dir->size.apparent, (intmax_t)dir->size.actual, (intmax_t)dir->size.count);
	xml_dump(duc, dir, 1);
	printf("</duc>\n");
	ddir_free(dir);
	duc_close(duc);
	return 0;
}

/* JSON */

static void json_str(const char *s)
{
	fputs(s, stdout);
}

static void json_dump(struct duc *duc, struct ddir *dir, int depth);

static void json_ent(struct duc *duc, struct ddir *dir, struct dirent_d *e, int depth)
{
	int ind = depth * 2;
	printf("%*s{\n", ind, "");
	printf("%*s  \"name\": \"", ind, ""); json_str(e->name); printf("\",\n");
	if(e->type == FT_DIR) printf("%*s  \"count\": %jd,\n", ind, "", (intmax_t)e->size.count);
	printf("%*s  \"size_apparent\": %jd,\n", ind, "", (intmax_t)e->size.apparent);
	printf("%*s  \"size_actual\": %jd", ind, "", (intmax_t)e->size.actual);
	if(e->type == FT_DIR) {
		printf(",\n%*s  \"children\": [\n", ind, "");
		struct ddir *child = ddir_openent(duc, dir, e);
		if(child) {
			json_dump(duc, child, depth + 2);
			ddir_free(child);
		}
		printf("%*s  ]\n", ind, "");
	} else {
		printf("\n");
	}
	printf("%*s}", ind, "");
}

static void json_dump(struct duc *duc, struct ddir *dir, int depth)
{
	ddir_sort(dir, ST_ACTUAL, SORT_SIZE);
	for(size_t i=0; i<dir->ent_count; i++) {
		struct dirent_d *e = &dir->ent[i];
		int skip = 0;
		if(g_ex_files && e->type != FT_DIR) skip = 1;
		if(size_get(&e->size, g_st) < g_min_size) skip = 1;
		if(!skip) json_ent(duc, dir, e, depth);
		if(i + 1 < dir->ent_count) printf(",\n");
		else printf("\n");
	}
}

int cmd_json(struct duc *duc, int argc, char **argv)
{
	g_min_size = g_opt.min_size ? atoll(g_opt.min_size) : 0;
	g_ex_files = g_opt.exclude_files;
	g_st = g_opt.apparent ? ST_APPARENT : ST_ACTUAL;
	if(open_db_read(duc, 1) != 0) return 1;
	const char *path = argc > 0 ? argv[0] : ".";
	struct ddir *dir = ddir_open(duc, path);
	if(!dir) {
		duc_log(LOG_FTL, "%s", duc_strerror(duc->err));
		duc_close(duc);
		return 1;
	}
	printf("{\n");
	printf("  \"name\": \""); json_str(dir->path); printf("\",\n");
	printf("  \"count\": %jd,\n", (intmax_t)dir->size.count);
	printf("  \"size_apparent\": %jd,\n", (intmax_t)dir->size.apparent);
	printf("  \"size_actual\": %jd,\n", (intmax_t)dir->size.actual);
	printf("  \"children\": [\n");
	json_dump(duc, dir, 2);
	printf("  ]\n");
	printf("}\n");
	ddir_free(dir);
	duc_close(duc);
	return 0;
}
