cd /workspace/src && cat > graph.c <<'EOF'
#include "duc.h"
#include <math.h>
#include <errno.h>
#include "graph.h"

enum { PAL_SIZE = 0, PAL_RAINBOW, PAL_GREYSCALE, PAL_MONOCHROME, PAL_CLASSIC };

struct label {
	char *text;
	int fontsize;
	int x, y;
};

struct gctx {
	struct duc *duc;
	struct graph_opts *o;
	FILE *f;
	int fmt;
	double cx, cy;
	double r_start, r_max;
	int grad_id;
	struct label *labels;
