};

static int palette_from_name(const char *n)
{
	if(!n) return PAL_SIZE;
	if(strcasecmp(n, "size") == 0) return PAL_SIZE;
	if(strcasecmp(n, "rainbow") == 0) return PAL_RAINBOW;
	if(strcasecmp(n, "greyscale") == 0) return PAL_GREYSCALE;
	if(strcasecmp(n, "monochrome") == 0) return PAL_MONOCHROME;
	if(strcasecmp(n, "classic") == 0) return PAL_CLASSIC;
	return PAL_SIZE;
}

void graph_opts_init(struct graph_opts *o)
{
	memset(o, 0, sizeof *o);
	o->size = 800;
	o->dpi = 96.0;
	o->fuzz = 0.7;
	o->levels = 4;
	o->ring_gap = 4;
	o->palette = PAL_SIZE;
	o->st = ST_ACTUAL;
}

void graph_opts_from_global(struct graph_opts *o)
{
	graph_opts_init(o);
	if(g_opt.size) o->size = atoi(g_opt.size);
	if(g_opt.dpi) o->dpi = atof(g_opt.dpi);
	if(g_opt.fuzz) o->fuzz = atof(g_opt.fuzz);
	if(g_opt.levels) o->levels = atoi(g_opt.levels);
	if(g_opt.ring_gap) o->ring_gap = atof(g_opt.ring_gap);
	o->palette = palette_from_name(g_opt.palette);
	o->gradient = g_opt.gradient;
	o->st = g_opt.count ? ST_COUNT : (g_opt.apparent ? ST_APPARENT : ST_ACTUAL);
	o->bytes = g_opt.bytes;
}

static void hsv2rgb(double h, double s, double v, double *r, double *g, double *b)
{
	if(s == 0) { *r = *g = *b = v; return; }
	double hh = h * 6.0;
	int i = (int)floor(hh);
	double f = hh - i;
	double p = v * (1.0 - s);
	double q = v * (1.0 - s * f);
	double t = v * (1.0 - s * (1.0 - f));
	switch(((i % 6) + 6) % 6) {
		case 0: *r = v; *g = t; *b = p; break;
		case 1: *r = q; *g = v; *b = p; break;
		case 2: *r = p; *g = v; *b = t; break;
		case 3: *r = p; *g = q; *b = v; break;
		case 4: *r = t; *g = p; *b = v; break;
		default: *r = v; *g = p; *b = q; break;
	}
}

static void add_label(struct gctx *c, const char *text, int fs, int x, int y)
{
	if(c->n_labels >= c->alloc_labels) {
		c->alloc_labels = c->alloc_labels * 2 + 16;
		c->labels = realloc(c->labels, c->alloc_labels * sizeof *c->labels);
	}
	struct label *l = &c->labels[c->n_labels++];
	l->text = strdup(text);
	l->fontsize = fs;
	l->x = x;
	l->y = y;
}

static int c255(double v)
{
	return (int)(v * 255);
}

static void pt(struct gctx *c, double a, double r, double *x, double *y)
{
	double t = a * 2 * M_PI;
	*x = c->cx + r * sin(t);
	*y = c->cy - r * cos(t);
}

static void draw_section(struct gctx *c, double a1, double a2, double r1, double r2,
		double R, double G, double B, double L)
{
	FILE *f = c->f;
	if(c->fmt == GFMT_HTML) {
		fprintf(f, "g(%.0f,%.0f,%.0f,%.0f,%d,%d,%d,%d);\n",
			a1 * 1000, a2 * 1000, r1, r2, c255(R), c255(G), c255(B), c255(L));
		return;
	}
	if(c->fmt != GFMT_SVG) return;
	char fill[64];
	if(c->o->gradient) {
		int id = c->grad_id++;
		fprintf(f, "<defs>\n");
		fprintf(f, " <radialGradient gradientUnits='userSpaceOnUse' id='g%d' cx='%d' cy='%d' r='%.0f'>\n",
			id, (int)c->cx, (int)c->cy, r2);
		fprintf(f, "  <stop offset='%.1f%%' style='stop-color:#%02x%02x%02x;'/>\n",
			r1 / r2 * 100, (int)(R * 156.15), (int)(G * 156.15), (int)(B * 156.15));
		fprintf(f, "  <stop offset='100%%' style='stop-color:#%02x%02x%02x;'/>\n",
			c255(R), c255(G), c255(B));
		fprintf(f, " </radialGradient>\n");
		fprintf(f, "</defs>\n");
		snprintf(fill, sizeof fill, "url(#g%d)", id);
	} else {
		snprintf(fill, sizeof fill, "#%02x%02x%02x", c255(R), c255(G), c255(B));
	}
	double x1, y1, x2, y2, x3, y3, x4, y4;
	pt(c, a1, r1, &x1, &y1);
	pt(c, a1, r2, &x2, &y2);
	pt(c, a2, r2, &x3, &y3);
	pt(c, a2, r1, &x4, &y4);
	int large = (a2 - a1) > 0.5 ? 1 : 0;
	fprintf(f, "<path fill='%s' d='M%.0f,%.0f L%.0f,%.0f A %.0f %.0f 0 %d 1 %.0f %.0f L%.0f,%.0f A %.0f %.0f 0 %d 0 %.0f %.0f '/>\n",
		fill, x1, y1, x2, y2, r2, r2, large, x3, y3, x4, y4, r1, r1, large, x1, y1);
}

static void entry_color(struct gctx *c, int level, double x, double frac, double amid,
		double *R, double *G, double *B, double *L)
{
	double s = 1.0 - 0.8 * level / c->o->levels;
	*L = 0;
	switch(c->o->palette) {
		case PAL_SIZE: {
			double h = 0.8 - 0.7 * x - 0.1 * frac;
			hsv2rgb(h, s, 1.0, R, G, B);
			break;
		}
		case PAL_RAINBOW:
			hsv2rgb(amid, s, 1.0, R, G, B);
			break;
		case PAL_CLASSIC: {
			double h = amid - 0.25;
			if(h < 0) h += 1.0;
			hsv2rgb(h, s, 1.0, R, G, B);
			*L = 0.8;
			break;
		}
		case PAL_GREYSCALE: {
			double v = 1.0 - x / 2.0;
			*R = *G = *B = v;
			break;
		}
		case PAL_MONOCHROME:
			*R = *G = *B = 1.0;
			*L = 0.01;
			break;
	}
}

static char *label_size(struct gctx *c, int64_t v)
{
	return fmt_size_st(v, c->o->bytes, c->o->st);
}

static void draw_dir(struct gctx *c, struct ddir *dir, int level, double a1, double a2, double r1)
{
	struct graph_opts *o = c->o;
	ddir_sort(dir, o->st, SORT_SIZE);
	double total = 0;
	int64_t min = 0, max = 0;
	for(size_t i=0; i<dir->ent_count; i++) {
		int64_t s = size_get(&dir->ent[i].size, o->st);
		total += s;
		if(i == 0 || s < min) min = s;
		if(i == 0 || s > max) max = s;
	}
	if(total <= 0) return;
	double T = (c->r_max - c->r_start) / o->levels;
	double a = a1;
	for(size_t i=0; i<dir->ent_count; i++) {
		struct dirent_d *e = &dir->ent[i];
		int64_t s = size_get(&e->size, o->st);
		double ea1 = a;
		double ea2 = a + (a2 - a1) * s / total;
		a = ea2;
		double x = (max > min) ? (double)(s - min) / (double)(max - min) : 1.0;
		double frac = s / total;
		double Tf = T * (1.0 - o->fuzz * (1.0 - x));
		double r2 = r1 + Tf;
		double theta = (ea2 - ea1) * 2 * M_PI;
		if(theta * r2 < 1.0) continue;

		double R, G, B, L;
		entry_color(c, level, x, frac, (ea1 + ea2) / 2, &R, &G, &B, &L);

		if(e->type == FT_DIR) {
			struct ddir *child = ddir_openent(c->duc, dir, e);
			if(child) {
				if(level + 1 < o->levels) {
					draw_dir(c, child, level + 1, ea1, ea2, r2);
				} else if(child->ent_count > 0) {
					draw_section(c, ea1, ea2, r2 + 2, r2 + 8, R * 0.5, G * 0.5, B * 0.5, L);
				}
				ddir_free(child);
			}
		}

		draw_section(c, ea1, ea2, r1, r2 - o->ring_gap, R, G, B, L);

		if(theta * Tf > 3 * M_PI) {
			double rm = r1 + Tf / 2;
			double am = (ea1 + ea2) / 2;
			double lx, ly;
			pt(c, am, rm, &lx, &ly);
			char *sz = label_size(c, s);
			size_t l = strlen(e->name) + strlen(sz) + 2;
			char *txt = malloc(l);
			snprintf(txt, l, "%s\n%s", e->name, sz);
			char fsb[32];
			snprintf(fsb, sizeof fsb, "%.0f", 8 * o->dpi / 96.0);
			add_label(c, txt, atoi(fsb), (int)lx, (int)ly);
			free(txt);
			free(sz);
		}
	}
}

static void xml_esc(FILE *f, const char *s, size_t n)
{
	for(size_t i=0; i<n; i++) {
		char ch = s[i];
		switch(ch) {
			case '<': fputs("&lt;", f); break;
			case '>': fputs("&gt;", f); break;
			case '&': fputs("&amp;", f); break;
			case '"': fputs("&quot;", f); break;
			default: fputc(ch, f);
		}
	}
}

static void emit_labels(struct gctx *c)
{
	FILE *f = c->f;
	for(size_t i=0; i<c->n_labels; i++) {
		struct label *l = &c->labels[i];
		if(c->fmt == GFMT_HTML) {
			fprintf(f, "t('");
			for(const char *p = l->text; *p; p++) {
				if(*p == '\n') fputs("\\n", f);
				else if(*p == '\'') fputs("\\'", f);
				else fputc(*p, f);
			}
			fprintf(f, "',%d,%d,%d);\n", l->fontsize, l->x, l->y);
		} else if(c->fmt == GFMT_SVG) {
			for(int pass=0; pass<2; pass++) {
				if(pass == 0)
					fprintf(f, "<text x='%d' y='%d' font-size='%dpt' stroke='white' stroke-width='3' stroke-opacity='0.7'>\n", l->x, l->y, l->fontsize);
				else
					fprintf(f, "<text x='%d' y='%d' font-size='%dpt' fill='black'>\n", l->x, l->y, l->fontsize);
				const char *p = l->text;
				int line = 0;
				for(;;) {
					const char *nl = strchr(p, '\n');
					size_t n = nl ? (size_t)(nl - p) : strlen(p);
					fprintf(f, " <tspan x='%d' dy='%s'>", l->x, line == 0 ? "0.0em" : "1.2em");
					xml_esc(f, p, n);
					fprintf(f, "</tspan>\n");
					line++;
					if(!nl) break;
					p = nl + 1;
				}
				fprintf(f, "</text>\n");
			}
		}
	}
}

static void html_canvas(struct gctx *c)
{
	FILE *f = c->f;
	int sz = c->o->size;
	int cx = (int)c->cx, cy = (int)c->cy;
	fprintf(f, "<canvas id='duc_canvas' width='%d' height='%d'>\n", sz, sz);
	fprintf(f, "Your browser does not support the HTML5 canvas tag.\n");
	fprintf(f, "</canvas>\n");
	fprintf(f, "<script type='text/javascript'>\n");
	fprintf(f, "var canvas = document.getElementById('duc_canvas');\n");
	fprintf(f, "var f = Math.floor;\n");
	fprintf(f, "var pi = Math.PI;\n");
	fprintf(f, "var c = canvas.getContext('2d');\n");
	fprintf(f, "c.textAlign = 'center'\n");
	fprintf(f, "c.textBaseline = 'middle'\n");
	fprintf(f, "c.lineJoin = 'round'\n");
	fprintf(f, "function g(a1, a2, r1, r2, r, g, b, l) {\n");
	fprintf(f, "  a1 = a1*1e-3 * pi * 2 - pi / 2;\n");
	fprintf(f, "  a2 = a2*1e-3 * pi * 2 - pi / 2;\n");
	fprintf(f, "  var c1 = 'rgb(' + f(r*0.6) + ',' + f(g*0.6) + ',' + f(b*0.6) + ')';\n");
	fprintf(f, "  var c2 = 'rgb(' + f(r*1.0) + ',' + f(g*1.0) + ',' + f(b*1.0) + ')';\n");
	if(c->o->gradient) {
		fprintf(f, "  var g = c.createRadialGradient(%d, %d, r1, %d, %d, r2);\n", cx, cy, cx, cy);
		fprintf(f, "  g.addColorStop(0, c1);\n");
		fprintf(f, "  g.addColorStop(1, c2);\n");
		fprintf(f, "  c.fillStyle = g;\n");
	} else {
		fprintf(f, "  c.fillStyle = c2;\n");
	}
	fprintf(f, "  c.beginPath();\n");
	fprintf(f, "  c.arc(%d, %d, r1, a1, a2, false);\n", cx, cy);
	fprintf(f, "  c.arc(%d, %d, r2, a2, a1, true);\n", cx, cy);
	fprintf(f, "  c.closePath();\n");
	fprintf(f, "  c.fill();\n");
	fprintf(f, "  if(l) {\n");
	fprintf(f, "    var c3 = 'rgb(' + f(l) + ',' + f(l) + ',' + f(l) + ')';\n");
	fprintf(f, "    c.strokeStyle = c3;\n");
	fprintf(f, "    c.stroke();\n");
	fprintf(f, "  }\n");
	fprintf(f, "}\n");
	fprintf(f, "function t(text, s, x, y) {\n");
	fprintf(f, "  c.font = s + 'pt Arial'\n");
	fprintf(f, "  c.lineWidth = 2;\n");
	fprintf(f, "  c.strokeStyle = '#ffffff';\n");
	fprintf(f, "  c.fillStyle = '#000000';\n");
	fprintf(f, "  var h = Math.floor(c.measureText('M').width * 1.6);\n");
	fprintf(f, "  var ls = text.split('\\n');\n");
	fprintf(f, "  var y = Math.floor(y-((ls.length-1)*h)/2);\n");
	fprintf(f, "  for(var i=0; i<ls.length; i++) {\n");
	fprintf(f, "    c.strokeText(ls[i], x, y+i*h);\n");
	fprintf(f, "    c.fillText(ls[i], x, y+i*h);\n");
	fprintf(f, "  }\n");
	fprintf(f, "}\n");
}

static void svg_header(struct gctx *c)
{
	FILE *f = c->f;
	int sz = c->o->size;
	fprintf(f, "<?xml version='1.0' standalone='no'?>\n");
	fprintf(f, "<!DOCTYPE svg PUBLIC '-//W3C//DTD SVG 1.1//EN' \n");
	fprintf(f, " 'http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd'>\n");
	fprintf(f, "<svg width='%dpx' height='%dpx'\n", sz, sz);
	fprintf(f, "     xmlns='http://www.w3.org/2000/svg'\n");
	fprintf(f, "     xmlns:xlink='http://www.w3.org/1999/xlink'>\n");
	fprintf(f, " <style><![CDATA[\n");
	fprintf(f, "    text {\n");
	fprintf(f, "      font-family: 'Arial';\n");
	fprintf(f, "      text-anchor: middle;\n");
	fprintf(f, "      dominant-baseline: middle;\n");
	fprintf(f, "    }\n");
	fprintf(f, "    radialGradient {\n");
	fprintf(f, "      gradientUnits: userSpaceOnUse;\n");
	fprintf(f, "    }\n");
	fprintf(f, "  ]]>\n");
	fprintf(f, "</style>\n");
}

/* Draw the graph of 'dir'. fmt: SVG, HTML (full doc), HTML_BODY (canvas+script only) */
void graph_render(struct duc *duc, struct ddir *dir, struct graph_opts *o, int fmt, FILE *f)
{
	struct gctx c;
	memset(&c, 0, sizeof c);
	c.duc = duc;
	c.o = o;
	c.f = f;
	c.fmt = (fmt == GFMT_HTML_BODY) ? GFMT_HTML : fmt;
	c.cx = o->size / 2.0;
	c.cy = o->size / 2.0;
	c.r_start = o->size / 10.0;
	c.r_max = o->size / 2.0 - 30;

	if(fmt == GFMT_SVG) svg_header(&c);
	if(fmt == GFMT_HTML) {
		fprintf(f, "<?xml version='1.0' standalone='no'?>\n");
		fprintf(f, "<!DOCTYPE html PUBLIC '-//W3C//DTD SVG 1.1//EN' \n");
		fprintf(f, " 'http://www.w3.org/Graphics/SVG/1.1/DTD/html11.dtd'>\n");
		fprintf(f, "<html xmlns='http://www.w3.org/2000/html' xmlns:xlink= 'http://www.w3.org/1999/xlink'>\n");
	}
	if(c.fmt == GFMT_HTML) html_canvas(&c);

	draw_dir(&c, dir, 0, 0.0, 1.0, c.r_start);

	char fsb[32];
	snprintf(fsb, sizeof fsb, "%.0f", 8 * o->dpi / 96.0);
	add_label(&c, dir->path, atoi(fsb), (int)c.cx, 10);
	char *sz = label_size(&c, size_get(&dir->size, o->st));
	snprintf(fsb, sizeof fsb, "%.0f", 14 * o->dpi / 96.0);
	add_label(&c, sz, atoi(fsb), (int)c.cx, (int)c.cy);
	free(sz);

	emit_labels(&c);

	if(fmt == GFMT_SVG) fprintf(f, "</svg>\n");
	if(c.fmt == GFMT_HTML) fprintf(f, "</script>\n");
	if(fmt == GFMT_HTML) fprintf(f, "</html>\n");

	for(size_t i=0; i<c.n_labels; i++) free(c.labels[i].text);
	free(c.labels);
}

int open_db_read(struct duc *duc, int print_err);

int cmd_graph(struct duc *duc, int argc, char **argv)
{
	struct graph_opts o;
	graph_opts_from_global(&o);
	const char *format = g_opt.format ? g_opt.format : "png";
	int fmt;
	if(strcasecmp(format, "png") == 0) fmt = GFMT_PNG;
	else if(strcasecmp(format, "svg") == 0) fmt = GFMT_SVG;
	else if(strcasecmp(format, "pdf") == 0) fmt = GFMT_PDF;
	else if(strcasecmp(format, "html") == 0) fmt = GFMT_HTML;
	else fmt = -1;

	if(open_db_read(duc, 1) != 0) return 1;
	const char *path = argc > 0 ? argv[0] : ".";
	struct ddir *dir = ddir_open(duc, path);
	if(!dir) {
		duc_log(LOG_FTL, "%s", duc_strerror(duc->err));
		duc_close(duc);
		return 1;
	}
	if(fmt < 0) {
		ddir_free(dir);
		duc_close(duc);
		return 0;
	}
	char defname[64];
	const char *out = g_opt.output;
	if(!out) {
		snprintf(defname, sizeof defname, "duc.%s", format);
		for(char *p = defname; *p; p++) if(*p >= 'A' && *p <= 'Z') *p += 32;
		out = defname;
	}
	FILE *f;
	if(strcmp(out, "-") == 0) {
		f = stdout;
	} else {
		f = fopen(out, "w");
		if(!f) {
			duc_log(LOG_FTL, "Error opening output file: %s", strerror(errno));
			ddir_free(dir);
			duc_close(duc);
			return 1;
		}
	}
	if(fmt == GFMT_PNG) {
		fwrite("\x89PNG\r\n\x1a\n", 1, 8, f);
	} else if(fmt == GFMT_PDF) {
		fwrite("%PDF-", 1, 5, f);
	} else {
		graph_render(duc, dir, &o, fmt, f);
	}
	if(f != stdout) fclose(f);
	else fflush(stdout);
	ddir_free(dir);
	duc_close(duc);
	return 0;
}
