cat /tmp/css.c >> cgi.c; cat >> cgi.c <<'EOF'

struct param { char *key; char *val; };
static struct param *params;
static int n_params;

static int hexval(int c)
{
	if(c >= '0' && c <= '9') return c - '0';
	if(c >= 'a' && c <= 'f') return c - 'a' + 10;
	if(c >= 'A' && c <= 'F') return c - 'A' + 10;
	return -1;
}

static char *url_decode(const char *s)
{
	char *r = malloc(strlen(s) + 1);
	char *o = r;
	while(*s) {
		if(*s == '+') { *o++ = ' '; s++; }
		else if(*s == '%' && hexval(s[1]) >= 0 && hexval(s[2]) >= 0) {
			*o++ = hexval(s[1]) * 16 + hexval(s[2]);
			s += 3;
		} else *o++ = *s++;
	}
	*o = 0;
	return r;
}

static void parse_query(const char *qs)
{
	if(!qs) return;
	char *t = strdup(qs);
	char *save = NULL;
	for(char *p = strtok_r(t, "&", &save); p; p = strtok_r(NULL, "&", &save)) {
		char *eq = strchr(p, '=');
		char *k, *v;
		if(eq) { *eq = 0; k = p; v = eq + 1; }
		else { k = p; v = ""; }
		params = realloc(params, sizeof(*params) * (n_params + 1));
		params[n_params].key = url_decode(k);
		params[n_params].val = url_decode(v);
		n_params++;
	}
	free(t);
}

static const char *param(const char *k)
{
	const char *r = NULL;
	for(int i=0; i<n_params; i++) {
		if(strcmp(params[i].key, k) == 0) r = params[i].val;
	}
	return r;
}

static void print_url_enc(const char *s)
{
	for(const unsigned char *p = (const unsigned char *)s; *p; p++) {
		if(isalnum(*p) || strchr("-_.!*()$+/", *p)) putchar(*p);
		else printf("%%%02x", *p);
	}
}

static void print_html_esc(const char *s)
{
	for(; *s; s++) {
		switch(*s) {
			case '<': fputs("&lt;", stdout); break;
			case '>': fputs("&gt;", stdout); break;
			case '&': fputs("&amp;", stdout); break;
			case '"': fputs("&quot;", stdout); break;
			default: putchar(*s);
		}
	}
}

static const char *script_name;

static void print_include(const char *fname)
{
	if(!fname) return;
	FILE *f = fopen(fname, "r");
	if(!f) return;
	printf("<!-- start include -->\n");
	char buf[4096];
	size_t n;
	while((n = fread(buf, 1, sizeof buf, f)) > 0) fwrite(buf, 1, n, stdout);
	fclose(f);
	printf("<!-- end include -->\n");
}

static void print_script(const char *path)
{
	printf("<script>\n");
	printf("  window.onload = function() {\n");
	printf("    var img = document.getElementById('duc_canvas');\n");
	printf("    var tt = document.getElementById('tooltip');\n");
	printf("    var timer;\n");
	printf("    img.onmousedown = function(e) {\n");
	printf("      if(e.button == 0) {\n");
	printf("        var rect = img.getBoundingClientRect(img);\n");
	printf("        var x = e.clientX - rect.left;\n");
	printf("        var y = e.clientY - rect.top;\n");
	printf("        window.location = '?x=' + x + '&y=' + y + '&path=%s';\n", path);
	printf("      }\n");
	printf("    }\n");
	if(g_opt.tooltip) {
		printf("    img.onmouseout = function() { tt.style.display = \"none\"; };\n");
		printf("    img.onmousemove = function(e) {\n");
		printf("      if(timer) clearTimeout(timer);\n");
		printf("      timer = setTimeout(function() {\n");
		printf("        var rect = img.getBoundingClientRect(img);\n");
		printf("        var x = e.clientX - rect.left;\n");
		printf("        var y = e.clientY - rect.top;\n");
		printf("        var req = new XMLHttpRequest();\n");
		printf("        req.onreadystatechange = function() {\n");
		printf("          if(req.readyState == 4 && req.status == 200) {\n");
		printf("            tt.style.display = tt.innerHTML.length > 0 ? \"block\" : \"none\";\n");
		printf("            tt.style.left = (e.pageX - tt.offsetWidth / 2) + \"px\";\n");
		printf("            tt.style.top = (e.pageY - tt.offsetHeight - 5) + \"px\";\n");
		printf("            tt.innerHTML = req.responseText;\n");
		printf("          }\n");
		printf("        };\n");
		printf("        req.open(\"GET\", \"?cmd=tooltip&path=%s&x=\"+x+\"&y=\"+y , true);\n", path);
		printf("        req.send()\n");
		printf("      }, 100);\n");
		printf("    };\n");
	}
	printf("  };\n");
	printf("</script>\n");
}

static void print_index_table(struct duc *duc)
{
	printf("<div id=index> <table>\n");
	printf("  <tr>\n");
	printf("   <th>Path</th>\n");
	printf("   <th>Size</th>\n");
	printf("   <th>Files</th>\n");
	printf("   <th>Directories</th>\n");
	printf("   <th>Date</th>\n");
	printf("   <th>Time</th>\n");
	printf("  </tr>\n");
	char **list = NULL; size_t n = 0;
	if(duc->db) report_get_list(duc, &list, &n);
	for(size_t i=0; i<n; i++) {
		struct report *r = report_load(duc, list[i]);
		if(!r) continue;
		time_t tt = r->ts_sec;
		struct tm *tm = localtime(&tt);
		char date[32], tim[32];
		strftime(date, sizeof date, "%Y-%m-%d", tm);
		strftime(tim, sizeof tim, "%H:%M:%S", tm);
		char *sz = fmt_size(g_opt.apparent ? r->size.apparent : r->size.actual, 0, 1024);
		printf("  <tr>\n");
		printf("   <td><a href=\"%s?cmd=index&path=", script_name);
		print_url_enc(r->path);
		printf("\">");
		print_html_esc(r->path);
		printf("</a></td>\n");
		printf("   <td>%s</td>\n", sz);
		printf("   <td>%jd</td>\n", (intmax_t)r->file_count);
		printf("   <td>%jd</td>\n", (intmax_t)r->dir_count);
		printf("   <td>%s</td>\n", date);
		printf("   <td>%s</td>\n", tim);
		printf("  </tr>\n");
		free(sz);
		report_free(r);
	}
	for(size_t i=0; i<n; i++) free(list[i]);
	free(list);
	printf(" </table>\n");
}

static void print_list(struct duc *duc, struct ddir *dir, int st)
{
	ddir_sort(dir, st, SORT_SIZE);
	printf("<div id=list>\n");
	printf(" <table>\n");
	printf("  <tr>\n");
	printf("   <th class=name>Filename</th>\n");
	printf("   <th class=size>Size</th>\n");
	printf("  </tr>\n");
	size_t n = dir->ent_count < 40 ? dir->ent_count : 40;
	for(size_t i=0; i<n; i++) {
		struct dirent_d *e = &dir->ent[i];
		char *sz = fmt_size_st(size_get(&e->size, st), g_opt.bytes, st);
		if(e->type == FT_DIR) {
			printf("  <tr><td class=name><a href=\"%s?cmd=index&path=", script_name);
			size_t l = strlen(dir->path) + strlen(e->name) + 2;
			char *p = malloc(l);
			if(strcmp(dir->path, "/") == 0) snprintf(p, l, "/%s", e->name);
			else snprintf(p, l, "%s/%s", dir->path, e->name);
			print_url_enc(p);
