int cmd_cgi(struct duc *duc, int argc, char **argv)
{
	if(getenv("GATEWAY_INTERFACE") == NULL) {
		fprintf(stderr, "The 'cgi' subcommand is used for integrating Duc into a web server.\n"
			"Please refer to the documentation for instructions how to install and configure.\n");
		return 1;
	}
	script_name = getenv("SCRIPT_NAME");
	if(!script_name) return 0;
	parse_query(getenv("QUERY_STRING"));

	struct graph_opts o;
	graph_opts_from_global(&o);
	int st = o.st;

	char *dbpath = g_opt.database ? strdup(g_opt.database) : duc_default_db_path();
	if(dbpath) {
		duc->db = db_open(dbpath, 0, &duc->err);
	}

	const char *cmd = param("cmd");
	if(!cmd) cmd = "index";
	const char *path = param("path");
	const char *sx = param("x");
	const char *sy = param("y");

	if(strcmp(cmd, "tooltip") == 0) {
		if(!path) return 0;
		char *np = path_normalize(path);
		struct ddir *dir = ddir_open(duc, np);
		free(np);
		if(!dir) { path_not_found(path); return 1; }
		printf("Content-Type: text/html\n\n");
		if(sx && sy) {
			struct dirent_d *e = NULL;
			char *ep = NULL;
			if(graph_lookup(duc, dir, &o, atoi(sx), atoi(sy), &e, &ep)) {
				char *sa = fmt_size(e->size.actual, g_opt.bytes, 1024);
				char *sp = fmt_size(e->size.apparent, g_opt.bytes, 1024);
				printf("name: %s<br>\n", e->name);
				printf("type: %s<br>\n", type_name(e->type));
				printf("actual size: %s<br>\n", sa);
				printf("apparent size: %s<br>\n", sp);
				printf("file count: %jd", (intmax_t)e->size.count);
				free(sa); free(sp);
			}
		}
		fflush(stdout);
		ddir_free(dir);
		return 0;
	}

	if(strcmp(cmd, "index") != 0) return 0;

	struct ddir *dir = NULL;
	if(path) {
		char *np = path_normalize(path);
		dir = ddir_open(duc, np);
		free(np);
		if(!dir) { path_not_found(path); return 1; }

		if(sx && sy) {
			double x = atoi(sx), y = atoi(sy);
