#include "duc.h"
#include <ncurses.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>

int open_db_read(struct duc *duc, int print_err);
extern const char *ui_help_text;

enum {
	PAIR_HEADER = 1,
	PAIR_CURSOR,
	PAIR_NORMAL,
	PAIR_NAME,
	PAIR_CLASS,
	PAIR_BAR,
};

static int use_color = 1;
static int opt_apparent, opt_bytes, opt_count, opt_name_sort, opt_topn;
static int64_t topn_cnt;

static int attr_header(void) { return use_color ? COLOR_PAIR(PAIR_HEADER) : A_REVERSE; }
static int attr_cursor(void) { return use_color ? COLOR_PAIR(PAIR_CURSOR) : A_REVERSE; }
static int attr_normal(void) { return use_color ? COLOR_PAIR(PAIR_NORMAL) : A_NORMAL; }
static int attr_name(void) { return use_color ? COLOR_PAIR(PAIR_NAME) : A_BOLD; }
static int attr_class(void) { return use_color ? COLOR_PAIR(PAIR_CLASS) : A_NORMAL; }
static int attr_bar(void) { return use_color ? COLOR_PAIR(PAIR_BAR) : A_NORMAL; }

static int cur_st(void)
{
	if(opt_count) return ST_COUNT;
	if(opt_apparent) return ST_APPARENT;
	return ST_ACTUAL;
}

struct pos {
	int cursor;
	int top;
};

static void draw(struct ddir *dir, struct pos *p)
{
	int H = LINES, W = COLS;
	int st = cur_st();
	int rows = H - 2;

	erase();

	/* header */
	attrset(attr_header());
	mvhline(0, 0, ' ', W);
	if(opt_topn) mvprintw(0, 1, " %jd largest files", (intmax_t)topn_cnt);
	else mvprintw(0, 1, " %s", dir->path);

	int64_t max = 0;
	size_t nfiles = 0, ndirs = 0;
	for(size_t i=0; i<dir->ent_count; i++) {
		int64_t s = size_get(&dir->ent[i].size, st);
		if(s > max) max = s;
		if(dir->ent[i].type == FT_DIR) ndirs++; else nfiles++;
	}

	int size_w = opt_bytes ? 12 : 7;
	int bar_w = W / 2;
	int name_w = W - 5 - size_w - bar_w;
	if(name_w < 18) {
		name_w = 18;
		bar_w = W - 5 - size_w - name_w;
	}

	for(int r=0; r<rows; r++) {
		int i = p->top + r;
		int y = r + 1;
		if(i >= (int)dir->ent_count) {
			attrset(attr_normal() | A_DIM);
			mvaddstr(y, 0, "~");
			continue;
		}
		struct dirent_d *e = &dir->ent[i];
		int is_cur = (i == p->cursor);
		int64_t s = size_get(&e->size, st);
		char *ss = fmt_size_st(s, opt_bytes, st);

		attrset(is_cur ? attr_cursor() : attr_normal());
		mvprintw(y, 0, "%*s ", size_w, ss);
		free(ss);

		size_t nl = strlen(e->name);
		int printed = 0;
		if(!is_cur) attrset(attr_name());
		if(bar_w > 0 && (int)nl > name_w) {
			addnstr(e->name, name_w);
			printed = name_w;
		} else {
			addstr(e->name);
			printed = nl;
			if(bar_w <= 0 || printed < name_w) {
				if(!is_cur) attrset(attr_class());
				addch(type_char(e->type));
				printed++;
			}
		}
		if(bar_w > 0) {
			if(!is_cur) attrset(attr_normal());
			for(int k=printed; k<name_w; k++) addch(' ');
			if(!is_cur) attrset(attr_bar());
			addstr(" [");
			int n = max > 0 ? (int)((__int128)s * bar_w / max) : 0;
			for(int k=0; k<bar_w; k++) addch(k < n ? '=' : ' ');
			addch(']');
		}
	}

	/* footer */
	attrset(attr_header());
	mvhline(H - 1, 0, ' ', W);
	if(st == ST_COUNT) {
		char *t = fmt_size(dir->size.count, opt_bytes, 1000);
		mvprintw(H - 1, 0, " Total %s files, %zu files and %zu directories here", t, nfiles, ndirs);
		free(t);
	} else {
		char *t = fmt_size(size_get(&dir->size, st), opt_bytes, 1024);
		mvprintw(H - 1, 0, " Total %sB in %zu files and %zu directories (%s size)", t, nfiles, ndirs,
			st == ST_APPARENT ? "apparent" : "actual");
		free(t);
	}
	attrset(A_NORMAL);
	refresh();
}

static void show_help(void)
{
	def_prog_mode();
	endwin();
	FILE *f = popen("less", "w");
	if(f) {
		fputs(ui_help_text, f);
		pclose(f);
	}
	reset_prog_mode();
	refresh();
}

static void sort_dir(struct ddir *dir)
{
	ddir_sort(dir, cur_st(), opt_name_sort ? SORT_NAME : SORT_SIZE);
}

struct stack {
	struct ddir *dir;
	struct pos pos;
};

int cmd_ui(struct duc *duc, int argc, char **argv)
{
	opt_apparent = g_opt.apparent;
	opt_bytes = g_opt.bytes;
	opt_count = g_opt.count;
	opt_name_sort = g_opt.name_sort;
	use_color = !g_opt.no_color;

	if(open_db_read(duc, 0) != 0) return 1;

	char cwd[16384];
	const char *path = argc > 0 ? argv[0] : (getcwd(cwd, sizeof cwd) ? cwd : ".");
	char *np = path_normalize(path);
	struct ddir *dir = ddir_open(duc, np);
	free(np);
	if(!dir) {
		fprintf(stderr, "The requested path '%s' was not found in the database,\n", path);
		fprintf(stderr, "Please run 'duc info' for a list of available directories.\n");
		duc_close(duc);
		return 1;
	}
	free(dir->path);
	dir->path = path_normalize(path);

	/* topn count from reports */
	{
		char **list; size_t n;
		report_get_list(duc, &list, &n);
		for(size_t i=0; i<n; i++) {
			struct report *r = report_load(duc, list[i]);
			if(r) { topn_cnt = r->topn_cnt; report_free(r); }
			free(list[i]);
		}
		free(list);
	}

	initscr();
	cbreak();
	noecho();
	keypad(stdscr, TRUE);
	nonl();
	curs_set(0);
	if(use_color && has_colors()) {
		start_color();
		init_pair(PAIR_HEADER, COLOR_WHITE, COLOR_BLUE);
		init_pair(PAIR_CURSOR, COLOR_BLACK, COLOR_CYAN);
		init_pair(PAIR_NORMAL, COLOR_WHITE, COLOR_BLACK);
		init_pair(PAIR_NAME, COLOR_GREEN, COLOR_BLACK);
		init_pair(PAIR_CLASS, COLOR_YELLOW, COLOR_BLACK);
		init_pair(PAIR_BAR, COLOR_CYAN, COLOR_BLACK);
		bkgdset(COLOR_PAIR(PAIR_NORMAL));
	} else {
		use_color = 0;
	}

	struct stack *stk = NULL;
	int nstk = 0;
	struct pos pos = { 0, 0 };
	sort_dir(dir);

	for(;;) {
		int rows = LINES - 2;
		if(rows < 1) rows = 1;
		int n = dir->ent_count;
		if(pos.cursor >= n) pos.cursor = n - 1;
		if(pos.cursor < 0) pos.cursor = 0;
		if(pos.cursor < pos.top) pos.top = pos.cursor;
		if(pos.cursor >= pos.top + rows) pos.top = pos.cursor - rows + 1;
		if(pos.top < 0) pos.top = 0;
		draw(dir, &pos);
		int c = getch();
		if(c == 'q' || c == 27) break;
		switch(c) {
			case KEY_UP: case 'k': pos.cursor--; break;
			case KEY_DOWN: case 'j': pos.cursor++; break;
			case KEY_PPAGE: pos.cursor -= rows; break;
			case KEY_NPAGE: pos.cursor += rows; break;
			case KEY_HOME: case '0': pos.cursor = 0; break;
			case KEY_END: case '$': pos.cursor = n - 1; break;
			case 'a': opt_apparent = !opt_apparent; sort_dir(dir); break;
			case 'b': opt_bytes = !opt_bytes; break;
			case 'c': opt_count = !opt_count; sort_dir(dir); break;
			case 'n': opt_name_sort = !opt_name_sort; sort_dir(dir); break;
			case 't': opt_topn = !opt_topn; break;
			case 'h': show_help(); break;
			case 'o': {
				if(n > 0) {
					struct dirent_d *e = &dir->ent[pos.cursor];
					size_t l = strlen(dir->path) + strlen(e->name) + 2;
					char *fp = malloc(l);
					snprintf(fp, l, "%s/%s", dir->path, e->name);
					def_prog_mode();
					endwin();
					pid_t pid = fork();
					if(pid == 0) {
						execlp("xdg-open", "xdg-open", fp, (char *)NULL);
						_exit(1);
					} else if(pid > 0) {
						int status;
						waitpid(pid, &status, 0);
					}
					reset_prog_mode();
					refresh();
					free(fp);
				}
				break;
			}
			case KEY_RIGHT: case '\n': case '\r': case KEY_ENTER: {
				if(n > 0) {
					struct dirent_d *e = &dir->ent[pos.cursor];
					if(e->type == FT_DIR) {
						struct ddir *child = ddir_openent(duc, dir, e);
						if(child) {
							stk = realloc(stk, sizeof(*stk) * (nstk + 1));
							stk[nstk].dir = dir;
							stk[nstk].pos = pos;
							nstk++;
							dir = child;
							pos.cursor = 0;
							pos.top = 0;
							sort_dir(dir);
						}
					}
				}
				break;
			}
			case KEY_LEFT: case KEY_BACKSPACE: case 127: case 8: {
				if(nstk > 0) {
					ddir_free(dir);
					nstk--;
					dir = stk[nstk].dir;
					pos = stk[nstk].pos;
					sort_dir(dir);
				}
				break;
			}
			default:
				break;
		}
	}

	endwin();
	while(nstk > 0) { nstk--; ddir_free(stk[nstk].dir); }
	free(stk);
	ddir_free(dir);
	duc_close(duc);
	return 0;
}
