#include "duc.h"
#include <dlfcn.h>

int open_db_read(struct duc *duc, int print_err);

int cmd_gui(struct duc *duc, int argc, char **argv)
{
	if(open_db_read(duc, 0) != 0) return 1;
	const char *path = argc > 0 ? argv[0] : ".";
	char *np = path_normalize(path);
	struct ddir *dir = ddir_open(duc, np);
	free(np);
	if(!dir) {
		fprintf(stderr, "The requested path '%s' was not found in the database,\n", path);
		fprintf(stderr, "Please run 'duc info' for a list of available directories.\n");
		duc_close(duc);
		return 1;
	}
	/* Try to connect to the X server; the graphical interface itself is not
	 * available in this build, so report the display as unavailable when no
	 * connection can be made. */
	void *dpy = NULL;
	void *lib = dlopen("libX11.so.6", RTLD_LAZY);
	if(lib) {
		void *(*xopen)(const char *) = (void *(*)(const char *))dlsym(lib, "XOpenDisplay");
		int (*xclose)(void *) = (int (*)(void *))dlsym(lib, "XCloseDisplay");
		if(xopen) dpy = xopen(NULL);
		if(dpy && xclose) xclose(dpy);
	}
	fprintf(stderr, "ERROR: Could not open display\n");
	ddir_free(dir);
	duc_close(duc);
	return 1;
}
